207	    auto getJSONParserAndElement()
208	    {
209	#if USE_SIMDJSON
210	        return std::pair<SimdJSONParser, SimdJSONParser::Element>();
211	#elif USE_RAPIDJSON
212	        return std::pair<RapidJSONParser, RapidJSONParser::Element>();
213	#else
214	        return std::pair<DummyJSONParser, DummyJSONParser::Element>();
215	#endif
216	    }
