218	    DataTypePtr getDataTypeFromField(const String & field)
219	    {
220	        auto [parser, element] = getJSONParserAndElement();
221	        bool parsed = parser.parse(field, element);
222	        if (!parsed)
223	            throw Exception(ErrorCodes::INCORRECT_DATA, "Cannot parse JSON object here: {}", field);
224	
225	        return getDataTypeFromFieldImpl(element);
