3355	void MergeTreeData::delayInsertOrThrowIfNeeded(Poco::Event * until, ContextPtr query_context) const
3356	{
3357	    const auto settings = getSettings();
3358	    const auto & query_settings = query_context->getSettingsRef();
3359	    const size_t parts_count_in_total = getPartsCount();
3360	    if (parts_count_in_total >= settings->max_parts_in_total)
3361	    {
3362	        ProfileEvents::increment(ProfileEvents::RejectedInserts);
3363	        throw Exception("Too many parts (" + toString(parts_count_in_total) + ") in all partitions in total. This indicates wrong choice of partition key. The threshold can be modified with 'max_parts_in_total' setting in <merge_tree> element in config.xml or with per-table setting.", ErrorCodes::TOO_MANY_PARTS);
3364	    }
3365	
3366	    size_t parts_count_in_partition = getMaxPartsCountForPartition();
3367	    ssize_t k_inactive = -1;
3368	    if (settings->inactive_parts_to_throw_insert > 0 || settings->inactive_parts_to_delay_insert > 0)
3369	    {
3370	        size_t inactive_parts_count_in_partition = getMaxInactivePartsCountForPartition();
3371	        if (settings->inactive_parts_to_throw_insert > 0 && inactive_parts_count_in_partition >= settings->inactive_parts_to_throw_insert)
3372	        {
3373	            ProfileEvents::increment(ProfileEvents::RejectedInserts);
3374	            throw Exception(
3375	                ErrorCodes::TOO_MANY_PARTS,
3376	                "Too many inactive parts ({}). Parts cleaning are processing significantly slower than inserts",
3377	                inactive_parts_count_in_partition);
3378	        }
3379	        k_inactive = static_cast<ssize_t>(inactive_parts_count_in_partition) - static_cast<ssize_t>(settings->inactive_parts_to_delay_insert);
3380	    }
3381	
3382	    auto parts_to_delay_insert = query_settings.parts_to_delay_insert.changed ? query_settings.parts_to_delay_insert : settings->parts_to_delay_insert;
3383	    auto parts_to_throw_insert = query_settings.parts_to_throw_insert.changed ? query_settings.parts_to_throw_insert : settings->parts_to_throw_insert;
3384	
3385	    if (parts_count_in_partition >= parts_to_throw_insert)
3386	    {
3387	        ProfileEvents::increment(ProfileEvents::RejectedInserts);
3388	        throw Exception(
3389	            ErrorCodes::TOO_MANY_PARTS,
3390	            "Too many parts ({}). Merges are processing significantly slower than inserts",
3391	            parts_count_in_partition);
3392	    }
3393	
3394	    if (k_inactive < 0 && parts_count_in_partition < parts_to_delay_insert)
3395	        return;
3396	
3397	    const ssize_t k_active = ssize_t(parts_count_in_partition) - ssize_t(parts_to_delay_insert);
3398	    size_t max_k;
3399	    size_t k;
3400	    if (k_active > k_inactive)
3401	    {
3402	        max_k = parts_to_throw_insert - parts_to_delay_insert;
3403	        k = k_active + 1;
3404	    }
3405	    else
3406	    {
3407	        max_k = settings->inactive_parts_to_throw_insert - settings->inactive_parts_to_delay_insert;
3408	        k = k_inactive + 1;
3409	    }
3410	    const double delay_milliseconds = ::pow(settings->max_delay_to_insert * 1000, static_cast<double>(k) / max_k);
3411	
3412	    ProfileEvents::increment(ProfileEvents::DelayedInserts);
3413	    ProfileEvents::increment(ProfileEvents::DelayedInsertsMilliseconds, delay_milliseconds);
3414	
3415	    CurrentMetrics::Increment metric_increment(CurrentMetrics::DelayedInserts);
3416	
3417	    LOG_INFO(log, "Delaying inserting block by {} ms. because there are {} parts", delay_milliseconds, parts_count_in_partition);
3418	
3419	    if (until)
3420	        until->tryWait(delay_milliseconds);
3421	    else
3422	        std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<size_t>(delay_milliseconds)));
3423	}
