70	/** Higher-order functions for arrays.
71	  * These functions optionally apply a map (transform) to array (or multiple arrays of identical size) by lambda function,
72	  *  and return some result based on that transformation.
73	  *
74	  * Examples:
75	  * arrayMap(x1,...,xn -> expression, array1,...,arrayn) - apply the expression to each element of the array (or set of parallel arrays).
76	  * arrayFilter(x -> predicate, array) - leave in the array only the elements for which the expression is true.
77	  *
78	  * For some functions arrayCount, arrayExists, arrayAll, an overload of the form f(array) is available,
79	  *  which works in the same way as f(x -> x, array).
80	  *
81	  * See the example of Impl template parameter in arrayMap.cpp
82	  */
83	template <typename Impl, typename Name>
84	class FunctionArrayMapped : public IFunction
85	{
86	public:
87	    static constexpr auto name = Name::name;
88	    static FunctionPtr create(ContextPtr) { return std::make_shared<FunctionArrayMapped>(); }
89	
90	    String getName() const override
91	    {
92	        return name;
93	    }
94	
95	    bool isVariadic() const override { return true; }
96	    size_t getNumberOfArguments() const override { return 0; }
97	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return true; }
98	
99	    /// Called if at least one function argument is a lambda expression.
100	    /// For argument-lambda expressions, it defines the types of arguments of these expressions.
101	    void getLambdaArgumentTypes(DataTypes & arguments) const override
102	    {
103	        if (arguments.empty())
104	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
105	                            "Function {} needs at least one argument, passed {}", getName(), arguments.size());
106	
107	        if (arguments.size() == 1)
108	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
109	                            "Function {} needs at least one argument with data", getName());
110	
111	        if (arguments.size() > 2 && Impl::needOneArray())
112	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
113	                            "Function {} needs one argument with data", getName());
114	
115	        size_t nested_types_count = std::is_same_v<typename Impl::data_type, DataTypeMap> ? (arguments.size() - 1) * 2 : (arguments.size() - 1);
116	        DataTypes nested_types(nested_types_count);
117	        for (size_t i = 0; i < arguments.size() - 1; ++i)
118	        {
119	            const auto * array_type = checkAndGetDataType<typename Impl::data_type>(&*arguments[i + 1]);
120	            if (!array_type)
121	                throw Exception("Argument " + toString(i + 2) + " of function " + getName() + " must be array. Found "
122	                                + arguments[i + 1]->getName() + " instead.", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
123	            if constexpr (std::is_same_v<typename Impl::data_type, DataTypeMap>)
124	            {
125	                nested_types[2 * i] = recursiveRemoveLowCardinality(array_type->getKeyType());
126	                nested_types[2 * i + 1] = recursiveRemoveLowCardinality(array_type->getValueType());
127	            }
128	            else if constexpr (std::is_same_v<typename Impl::data_type, DataTypeArray>)
129	            {
130	                nested_types[i] = recursiveRemoveLowCardinality(array_type->getNestedType());
131	            }
132	        }
133	
134	        const DataTypeFunction * function_type = checkAndGetDataType<DataTypeFunction>(arguments[0].get());
135	        if (!function_type || function_type->getArgumentTypes().size() != nested_types.size())
136	            throw Exception(
137	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
138	                "First argument for this overload of {} must be a function with {} arguments, found {} instead",
139	                getName(), nested_types.size(), arguments[0]->getName());
140	
141	        arguments[0] = std::make_shared<DataTypeFunction>(nested_types);
142	    }
143	
144	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
145	    {
146	        size_t min_args = Impl::needExpression() ? 2 : 1;
147	        if (arguments.size() < min_args)
148	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
149	                            "Function {} needs at least {} argument, passed {}",
150	                            getName(), min_args, arguments.size());
151	
152	        if ((arguments.size() == 1) && std::is_same_v<typename Impl::data_type, DataTypeArray>)
153	        {
154	            const auto * data_type = checkAndGetDataType<typename Impl::data_type>(arguments[0].type.get());
155	
156	            if (!data_type)
157	                throw Exception("The only argument for function " + getName() + " must be array. Found "
158	                                + arguments[0].type->getName() + " instead", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
159	
160	            DataTypePtr nested_type = data_type->getNestedType();
161	
162	            if (Impl::needBoolean() && !isUInt8(nested_type))
163	                throw Exception("The only argument for function " + getName() + " must be array of UInt8. Found "
164	                                + arguments[0].type->getName() + " instead", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
165	
166	            if constexpr (std::is_same_v<typename Impl::data_type, DataTypeArray>)
167	                return Impl::getReturnType(nested_type, nested_type);
168	            else
169	                throw DB::Exception(ErrorCodes::LOGICAL_ERROR, "Unreachable code reached");
170	        }
171	        else
172	        {
173	            if (arguments.size() > 2 && Impl::needOneArray())
174	                throw Exception("Function " + getName() + " needs one argument with data",
175	                    ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
176	
177	            const auto * data_type_function = checkAndGetDataType<DataTypeFunction>(arguments[0].type.get());
178	
179	            if (!data_type_function)
180	                throw Exception("First argument for function " + getName() + " must be a function",
181	                    ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
182	
183	            /// The types of the remaining arguments are already checked in getLambdaArgumentTypes.
184	
185	            DataTypePtr return_type = removeLowCardinality(data_type_function->getReturnType());
186	
187	            /// Special cases when we need boolean lambda result:
188	            ///  - lambda may return Nullable(UInt8) column, in this case after lambda execution we will
189	            ///    replace all NULLs with 0 and return nested UInt8 column.
190	            ///  - lambda may return Nothing or Nullable(Nothing) because of default implementation of functions
191	            ///    for these types. In this case we will just create UInt8 const column full of 0.
192	            if (Impl::needBoolean() && !isUInt8(removeNullable(return_type)) && !isNothing(removeNullable(return_type)))
193	                throw Exception("Expression for function " + getName() + " must return UInt8 or Nullable(UInt8), found "
194	                                + return_type->getName(), ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
195	
196	            static_assert(
197	                std::is_same_v<typename Impl::data_type, DataTypeMap> ||
198	                std::is_same_v<typename Impl::data_type, DataTypeArray>,
199	                "unsupported type");
200	
201	            if (arguments.size() < 2)
202	            {
203	                throw DB::Exception(ErrorCodes::LOGICAL_ERROR, "{}", arguments.size());
204	            }
205	
206	            const auto * first_array_type = checkAndGetDataType<typename Impl::data_type>(arguments[1].type.get());
207	
208	            if (!first_array_type)
209	                throw DB::Exception(ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT, "Unsupported type {}", arguments[1].type->getName());
210	
211	            if constexpr (std::is_same_v<typename Impl::data_type, DataTypeArray>)
212	                return Impl::getReturnType(return_type, first_array_type->getNestedType());
213	
214	            if constexpr (std::is_same_v<typename Impl::data_type, DataTypeMap>)
215	                return Impl::getReturnType(return_type, first_array_type->getKeyValueTypes());
216	
217	            throw DB::Exception(ErrorCodes::LOGICAL_ERROR, "Unreachable code reached");
218	        }
219	    }
