21	    template <template <typename, typename> class AggregateFunctionTemplate, template <typename> typename Data, typename... TArgs>
22	    IAggregateFunction * createWithIntegerType(const IDataType & argument_type, TArgs &&... args)
23	    {
24	        WhichDataType which(argument_type);
25	        if (which.idx == TypeIndex::UInt8) return new AggregateFunctionTemplate<UInt8, Data<UInt8>>(std::forward<TArgs>(args)...);
26	        if (which.idx == TypeIndex::UInt16) return new AggregateFunctionTemplate<UInt16, Data<UInt16>>(std::forward<TArgs>(args)...);
27	        if (which.idx == TypeIndex::UInt32) return new AggregateFunctionTemplate<UInt32, Data<UInt32>>(std::forward<TArgs>(args)...);
28	        if (which.idx == TypeIndex::UInt64) return new AggregateFunctionTemplate<UInt64, Data<UInt64>>(std::forward<TArgs>(args)...);
29	        if (which.idx == TypeIndex::Int8) return new AggregateFunctionTemplate<Int8, Data<Int8>>(std::forward<TArgs>(args)...);
30	        if (which.idx == TypeIndex::Int16) return new AggregateFunctionTemplate<Int16, Data<Int16>>(std::forward<TArgs>(args)...);
31	        if (which.idx == TypeIndex::Int32) return new AggregateFunctionTemplate<Int32, Data<Int32>>(std::forward<TArgs>(args)...);
32	        if (which.idx == TypeIndex::Int64) return new AggregateFunctionTemplate<Int64, Data<Int64>>(std::forward<TArgs>(args)...);
33	        return nullptr;
34	    }
35	
36	    template <template <typename> typename Data>
37	    AggregateFunctionPtr createAggregateFunctionBitmap(
38	        const std::string & name, const DataTypes & argument_types, const Array & parameters, const Settings *)
39	    {
40	        assertNoParameters(name, parameters);
41	        assertUnary(name, argument_types);
42	
43	        if (!argument_types[0]->canBeUsedInBitOperations())
44	            throw Exception(
45	                "The type " + argument_types[0]->getName() + " of argument for aggregate function " + name
46	                    + " is illegal, because it cannot be used in Bitmap operations",
47	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
48	
49	        AggregateFunctionPtr res(createWithIntegerType<AggregateFunctionBitmap, Data>(*argument_types[0], argument_types[0]));
50	
51	        if (!res)
52	            throw Exception(
53	                "Illegal type " + argument_types[0]->getName() + " of argument for aggregate function " + name,
54	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
55	
56	        return res;
57	    }
58	
59	    // Additional aggregate functions to manipulate bitmaps.
60	    template <template <typename, typename> typename AggregateFunctionTemplate>
61	    AggregateFunctionPtr createAggregateFunctionBitmapL2(
62	        const std::string & name, const DataTypes & argument_types, const Array & parameters, const Settings *)
63	    {
64	        assertNoParameters(name, parameters);
65	        assertUnary(name, argument_types);
66	
67	        DataTypePtr argument_type_ptr = argument_types[0];
68	        WhichDataType which(*argument_type_ptr);
69	        if (which.idx != TypeIndex::AggregateFunction)
70	            throw Exception(
71	                "Illegal type " + argument_types[0]->getName() + " of argument for aggregate function " + name,
72	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
73	
74	        /// groupBitmap needs to know about the data type that was used to create bitmaps.
75	        /// We need to look inside the type of its argument to obtain it.
76	        const DataTypeAggregateFunction & datatype_aggfunc = dynamic_cast<const DataTypeAggregateFunction &>(*argument_type_ptr);
77	        AggregateFunctionPtr aggfunc = datatype_aggfunc.getFunction();
78	        DataTypePtr nested_argument_type_ptr = aggfunc->getArgumentTypes()[0];
79	
80	        AggregateFunctionPtr res(createWithIntegerType<AggregateFunctionTemplate, AggregateFunctionGroupBitmapData>(
81	            *nested_argument_type_ptr, argument_type_ptr));
82	
83	        if (!res)
84	            throw Exception(
85	                "Illegal type " + argument_types[0]->getName() + " of argument for aggregate function " + name,
86	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
87	
88	        return res;
89	    }
