43	            printHelpMessage();
44	            throw DB::Exception("Bad Arguments", DB::ErrorCodes::BAD_ARGUMENTS);
45	        }
46	
47	        String disk_name = config.getString("disk", "default");
48	
49	        String path =  command_arguments[0];
50	
51	        DiskPtr disk = global_context->getDisk(disk_name);
52	
53	        String full_path = fullPathWithValidate(disk, path);
54	
55	        bool recursive = config.getBool("recursive", false);
56	
57	        if (recursive)
58	            listRecursive(disk, full_path);
59	        else
60	            list(disk, full_path);
