68	
69	        for (const auto & file_name : file_names)
70	            std::cout << file_name << '\n';
71	    }
72	
73	    static void listRecursive(const DiskPtr & disk, const std::string & full_path)
74	    {
75	        std::vector<String> file_names;
76	        disk->listFiles(full_path, file_names);
77	
78	        std::cout << full_path << ":\n";
79	        for (const auto & file_name : file_names)
80	            std::cout << file_name << '\n';
81	        std::cout << "\n";
82	
83	        for (const auto & file_name : file_names)
84	        {
85	            auto path = full_path + "/" + file_name;
