322	{
323	    if (first_row)
324	    {
325	        skipBOMIfExists(in);
326	        skipWhitespaceIfAny(in);
327	        if (checkChar('[', in))
328	            data_in_square_brackets = true;
329	        first_row = false;
330	    }
331	    else
332	    {
333	        skipWhitespaceIfAny(in);
334	        /// If data is in square brackets then ']' means the end of data.
335	        if (data_in_square_brackets && checkChar(']', in))
336	            return {};
337	
338	        /// ';' means end of data.
339	        if (checkChar(';', in))
340	            return {};
341	
342	        /// There may be optional ',' between rows.
343	        checkChar(',', in);
344	    }
345	
346	    skipWhitespaceIfAny(in);
347	    if (in.eof())
348	    {
349	        eof = true;
350	        return {};
351	    }
352	
353	    return JSONUtils::readRowAndGetNamesAndDataTypesForJSONEachRow(in, json_strings);
354	}
