53	/// This aggregate function takes the states of AggregateFunctionBitmap as its argument.
54	template <typename T, typename Data, typename Policy>
55	class AggregateFunctionBitmapL2 final : public IAggregateFunctionDataHelper<Data, AggregateFunctionBitmapL2<T, Data, Policy>>
56	{
57	private:
58	    static constexpr size_t STATE_VERSION_1_MIN_REVISION = 54455;
59	public:
60	    explicit AggregateFunctionBitmapL2(const DataTypePtr & type)
61	        : IAggregateFunctionDataHelper<Data, AggregateFunctionBitmapL2<T, Data, Policy>>({type}, {})
62	    {
63	    }
64	
65	    String getName() const override { return Policy::name; }
66	
67	    DataTypePtr getReturnType() const override { return std::make_shared<DataTypeNumber<T>>(); }
68	
69	    bool allocatesMemoryInArena() const override { return false; }
70	
71	    DataTypePtr getStateType() const override
72	    {
73	        return this->argument_types.at(0);
74	    }
75	
76	    void add(AggregateDataPtr __restrict place, const IColumn ** columns, size_t row_num, Arena *) const override
77	    {
78	        Data & data_lhs = this->data(place);
79	        const Data & data_rhs = this->data(assert_cast<const ColumnAggregateFunction &>(*columns[0]).getData()[row_num]);
80	        if (!data_lhs.init)
81	        {
82	            data_lhs.init = true;
83	            data_lhs.rbs.merge(data_rhs.rbs);
84	        }
85	        else
86	        {
87	            Policy::apply(data_lhs, data_rhs);
88	        }
89	    }
90	
91	    void merge(AggregateDataPtr __restrict place, ConstAggregateDataPtr rhs, Arena *) const override
92	    {
93	        Data & data_lhs = this->data(place);
94	        const Data & data_rhs = this->data(rhs);
95	
96	        if (!data_rhs.init)
97	            return;
98	
99	        if (!data_lhs.init)
100	        {
101	            data_lhs.init = true;
102	            data_lhs.rbs.merge(data_rhs.rbs);
103	        }
104	        else
105	        {
106	            Policy::apply(data_lhs, data_rhs);
107	        }
108	    }
109	
110	    bool isVersioned() const override { return true; }
111	
112	    size_t getDefaultVersion() const override { return 1; }
113	
114	    size_t getVersionFromRevision(size_t revision) const override
115	    {
116	        if (revision >= STATE_VERSION_1_MIN_REVISION)
117	            return 1;
118	        else
119	            return 0;
120	    }
121	
122	    void serialize(ConstAggregateDataPtr __restrict place, WriteBuffer & buf, std::optional<size_t> version) const override
123	    {
124	        if (!version)
125	            version = getDefaultVersion();
126	
127	        if (*version >= 1)
128	            DB::writeBoolText(this->data(place).init, buf);
129	
130	        this->data(place).rbs.write(buf);
131	    }
132	
133	    void deserialize(AggregateDataPtr __restrict place, ReadBuffer & buf, std::optional<size_t> version, Arena *) const override
134	    {
135	        if (!version)
136	            version = getDefaultVersion();
137	
138	        if (*version >= 1)
139	            DB::readBoolText(this->data(place).init, buf);
140	        this->data(place).rbs.read(buf);
141	    }
142	
143	    void insertResultInto(AggregateDataPtr __restrict place, IColumn & to, Arena *) const override
144	    {
145	        assert_cast<ColumnVector<T> &>(to).getData().push_back(this->data(place).rbs.size());
146	    }
147	};
