42	std::string replxx_now_ms_str()
43	{
44	    std::chrono::milliseconds ms(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()));
45	    time_t t = ms.count() / 1000;
46	    tm broken;
47	    if (!localtime_r(&t, &broken))
48	        return {};
49	
50	    static int const BUFF_SIZE(32);
51	    char str[BUFF_SIZE];
52	    if (strftime(str, BUFF_SIZE, "%Y-%m-%d %H:%M:%S.", &broken) <= 0)
53	        return {};
54	
55	    if (snprintf(str + sizeof("YYYY-mm-dd HH:MM:SS"), 5, "%03d", static_cast<int>(ms.count() % 1000)) <= 0)
56	        return {};
57	
58	    return str;
59	}
