244	void ReplxxLineReader::addToHistory(const String & line)
245	{
246	    // locking history file to prevent from inconsistent concurrent changes
247	    //
248	    // replxx::Replxx::history_save() already has lockf(),
249	    // but replxx::Replxx::history_load() does not
250	    // and that is why flock() is added here.
251	    bool locked = false;
252	    if (flock(history_file_fd, LOCK_EX))
253	        rx.print("Lock of history file failed: %s\n", errnoToString(errno).c_str());
254	    else
255	        locked = true;
256	
257	    rx.history_add(line);
258	
259	    // flush changes to the disk
260	    if (!rx.history_save(history_file_path))
261	        rx.print("Saving history failed: %s\n", errnoToString(errno).c_str());
262	
263	    if (locked && 0 != flock(history_file_fd, LOCK_UN))
264	        rx.print("Unlock of history file failed: %s\n", errnoToString(errno).c_str());
265	}
