409	{
410	    fprintf(out,
411	        "%s [--level=<level>] [--decompressor=<path>] <output_file> <input_file> [... <input_file>]\n"
412	        "\t--level - compression level, max is %d, negative - prefer speed over compression\n"
413	        "\t          default is 5\n"
