446	int main(int argc, char* argv[])
447	{
448	    if (argc == 1)
449	    {
450	        usage(stdout, argv[0]);
451	        return 0;
452	    }
453	
454	    int start_of_files = 1;
455	
456	    /// Set compression level
457	    int level = 5;
458	    const char * p = get_param(argc, argv, "level");
459	    if (p != nullptr)
460	    {
461	        if (p[0] != 0)
462	        {
463	            char * end = nullptr;
464	            level = strtol(p, &end, 10);
465	            if (*end != 0)
466	            {
467	                std::cerr << "Error: level [" << p << "] is not valid" << std::endl;
468	                usage(stderr, argv[0]);
469	                return 1;
470	            }
471	        }
472	        ++start_of_files;
473	    }
474	
475	    /// Set decompressor
476	    const char * decompressor = get_param(argc, argv, "decompressor");
477	    if (decompressor != nullptr)
478	    {
479	        if (decompressor[0] == 0)
480	            decompressor = nullptr;
481	        ++start_of_files;
482	    }
483	
484	    if (argc < start_of_files + 1)
485	    {
486	        usage(stderr, argv[0]);
487	        return 1;
488	    }
489	
490	    struct stat info_out;
491	    if (stat(argv[start_of_files], &info_out) != -1 || errno != ENOENT)
492	    {
493	        std::cerr << "Error: output file [" << argv[start_of_files] << "] already exists" << std::endl;
494	        return 1;
495	    }
496	
497	    int output_fd = open(argv[start_of_files], O_RDWR | O_CREAT, 0775);
498	    if (output_fd == -1)
499	    {
500	        perror(nullptr);
501	        return 1;
502	    }
503	    ++start_of_files;
504	
505	    if (decompressor != nullptr)
506	    {
507	        if (copy_decompressor_file(decompressor, output_fd))
508	            return 1;
509	    }
510	    else
511	    {
512	        if (copy_decompressor_self(argv[0], output_fd))
513	            return 1;
514	    }
515	
516	    if (0 != fstat(output_fd, &info_out))
517	    {
518	        perror(nullptr);
519	        return 1;
520	    }
521	
522	    std::cout << "Compression with level: " << level << std::endl;
523	    if (0 != compressFiles(&argv[start_of_files], argc - start_of_files, output_fd, level, info_out))
524	    {
525	        printf("Compression failed.\n");
526	        close(output_fd);
527	        unlink(argv[start_of_files - 1]);
528	        return 1;
529	    }
530	
531	    printf("Successfully compressed.\n");
532	
533	    if (0 != close(output_fd))
534	        perror(nullptr);
535	
536	    return 0;
537	}

