30	/// decompress part
31	int doDecompress(char * input, char * output, off_t & in_offset, off_t & out_offset,
32	               off_t input_size, off_t output_size, ZSTD_DCtx* dctx)
33	{
34	    size_t decompressed_size = ZSTD_decompressDCtx(dctx, output + out_offset, output_size, input + in_offset, input_size);
35	    if (ZSTD_isError(decompressed_size))
36	    {
37	        std::cerr << "Error (ZSTD):" << decompressed_size << " " << ZSTD_getErrorName(decompressed_size) << std::endl;
38	        return 1;
39	    }
40	    return 0;
41	}
