162	/// Read data about files and decomrpess them.
163	int decompressFiles(int input_fd, char * path, char * name, bool & have_compressed_analoge)
164	{
165	    /// Read data about output file.
166	    /// Compressed data will replace data in file
167	    struct stat info_in;
168	    if (0 != fstat(input_fd, &info_in))
169	    {
170	        perror(nullptr);
171	        return 1;
172	    }
173	
174	    /// mmap input file
175	    char * input = static_cast<char*>(mmap(nullptr, info_in.st_size, PROT_READ, MAP_PRIVATE, input_fd, 0));
176	    if (input == MAP_FAILED)
177	    {
178	        perror(nullptr);
179	        return 1;
180	    }
181	
182	    /// Read metadata from end of file
183	    MetaData metadata = *reinterpret_cast<MetaData*>(input + info_in.st_size - sizeof(MetaData));
184	
185	    /// Prepare to read information about files and decompress them
186	    off_t files_pointer = le64toh(metadata.start_of_files_data);
187	    size_t decompressed_full_size = 0;
188	
189	    /// Read files metadata and check if decompression is possible
190	    off_t check_pointer = le64toh(metadata.start_of_files_data);
191	    for (size_t i = 0; i < le64toh(metadata.number_of_files); ++i)
192	    {
193	        FileData data = *reinterpret_cast<FileData*>(input + check_pointer);
194	        decompressed_full_size += le64toh(data.uncompressed_size);
195	        check_pointer += sizeof(FileData) + le64toh(data.name_length);
196	    }
197	
198	    /// Check free space
199	    struct statfs fs_info;
200	    if (0 != fstatfs(input_fd, &fs_info))
201	    {
202	        perror(nullptr);
203	        if (0 != munmap(input, info_in.st_size))
204	                perror(nullptr);
