303	/// Set command to `mv filename.decompressed filename && filename agrs...`
304	void fillCommand(char command[], int argc, char * argv[], size_t length)
305	{
306	    memset(command, '\0', 3 + strlen(argv[0]) + 14 + strlen(argv[0]) + 4 + strlen(argv[0]) + length + argc);
307	
308	    /// position in command
309	    size_t shift = 0;
310	
311	    /// Support variables to create command
312	    char mv[] = "mv ";
313	    char decompressed[] = ".decompressed ";
314	    char add_command[] = " && ";
315	    char space[] = " ";
316	
317	    fill(command, mv, 3, shift);
318	    fill(command, argv[0], strlen(argv[0]), shift);
319	    fill(command, decompressed, 14, shift);
320	    fill(command, argv[0], strlen(argv[0]), shift);
321	    fill(command, add_command, 4, shift);
322	    fill(command, argv[0], strlen(argv[0]), shift);
323	    fill(command, space, 1, shift);
324	
325	    /// forward all arguments
326	    for (int i = 1; i < argc; ++i)
327	    {
328	        fill(command, argv[i], strlen(argv[i]), shift);
329	        if (i != argc - 1)
330	            fill(command, space, 1, shift);
331	    }
332	}
