334	int main(int argc, char* argv[])
335	{
336	    char file_path[strlen(argv[0]) + 1];
337	    memset(file_path, 0, sizeof(file_path));
338	    strcpy(file_path, argv[0]);
339	
340	    char * path = nullptr;
341	    char * name = strrchr(file_path, '/');
342	    if (name)
343	    {
344	        path = file_path;
345	        *name = 0;
346	        ++name;
347	    }
348	    else
349	        name = file_path;
350	
351	    int input_fd = open(argv[0], O_RDONLY);
352	    if (input_fd == -1)
353	    {
354	        perror(nullptr);
355	        return 1;
356	    }
357	
358	    bool have_compressed_analoge = false;
359	
360	    /// Decompress all files
361	    if (0 != decompressFiles(input_fd, path, name, have_compressed_analoge))
362	    {
363	        printf("Error happened during decompression.\n");
364	        if (0 != close(input_fd))
365	            perror(nullptr);
366	        return 1;
367	    }
368	
369	    if (0 != close(input_fd))
370	        perror(nullptr);
371	
372	    /// According to documentation `mv` will rename file if it
373	    /// doesn't move to other directory.
374	    /// Sometimes `rename` doesn't exist by default and
375	    /// `rename.ul` is set instead. It will lead to errors
376	    /// that can be easily avoided with help of `mv`
377	
378	    if (!have_compressed_analoge)
379	    {
380	        printf("No target executable - decompression only was performed.\n");
381	        /// remove file
382	        execlp("rm", "rm", argv[0], NULL);
383	        perror(nullptr);
384	        return 1;
385	    }
386	    else
387	    {
388	        /// move decompressed file instead of this binary and apply command
389	        char bash[] = "sh";
390	        char executable[] = "-c";
391	
392	        /// length of forwarded args
393	        size_t length = 0;
394	        for (int i = 1; i < argc; ++i)
395	            length += strlen(argv[i]);
396	
397	        /// mv filename.decompressed filename && filename agrs...
398	        char command[3 + strlen(argv[0]) + 14 + strlen(argv[0]) + 4 + strlen(argv[0]) + length + argc];
399	        fillCommand(command, argc, argv, length);
400	
401	        /// replace file and call executable
402	        char * newargv[] = { bash, executable, command, nullptr };
403	        execvp(bash, newargv);
404	
405	        /// This part of code will be reached only if error happened
406	        perror(nullptr);
407	        return 1;
408	    }
409	}

