17	OvercommitTracker::OvercommitTracker(std::mutex & global_mutex_)
18	    : picked_tracker(nullptr)
19	    , cancellation_state(QueryCancellationState::NONE)
20	    , global_mutex(global_mutex_)
21	    , freed_memory(0)
22	    , required_memory(0)
23	    , next_id(0)
24	    , id_to_release(0)
