145	void UserOvercommitTracker::pickQueryToExcludeImpl()
146	{
147	    MemoryTracker * query_tracker = nullptr;
148	    OvercommitRatio current_ratio{0, 0};
149	    // At this moment query list must be read only.
150	    // This is guaranteed by locking global_mutex in OvercommitTracker::needToStopQuery.
151	    auto & queries = user_process_list->queries;
152	    for (auto const & query : queries)
153	    {
154	        if (query.second->isKilled())
155	            continue;
156	
157	        auto * memory_tracker = query.second->getMemoryTracker();
158	        if (!memory_tracker)
159	            continue;
160	
161	        auto ratio = memory_tracker->getOvercommitRatio();
162	        if (ratio.soft_limit != 0 && current_ratio < ratio)
163	        {
164	            query_tracker = memory_tracker;
165	            current_ratio   = ratio;
166	        }
167	    }
168	    picked_tracker = query_tracker;
169	}
