176	void GlobalOvercommitTracker::pickQueryToExcludeImpl()
177	{
178	    MemoryTracker * query_tracker = nullptr;
179	    OvercommitRatio current_ratio{0, 0};
180	    // At this moment query list must be read only.
181	    // This is guaranteed by locking global_mutex in OvercommitTracker::needToStopQuery.
182	    for (auto const & query : process_list->processes)
183	    {
184	        if (query.isKilled())
185	            continue;
186	
187	        Int64 user_soft_limit = 0;
188	        if (auto const * user_process_list = query.getUserProcessList())
189	            user_soft_limit = user_process_list->user_memory_tracker.getSoftLimit();
190	        if (user_soft_limit == 0)
191	            continue;
192	
193	        auto * memory_tracker = query.getMemoryTracker();
194	        if (!memory_tracker)
195	            continue;
196	        auto ratio = memory_tracker->getOvercommitRatio(user_soft_limit);
197	        if (current_ratio < ratio)
198	        {
199	            query_tracker = memory_tracker;
200	            current_ratio   = ratio;
201	        }
202	    }
203	    picked_tracker = query_tracker;
204	}
