92	void Connection::connect(const ConnectionTimeouts & timeouts)
93	{
94	    try
95	    {
96	        LOG_TRACE(log_wrapper.get(), "Connecting. Database: {}. User: {}{}{}",
97	            default_database.empty() ? "(not specified)" : default_database,
98	            user,
99	            static_cast<bool>(secure) ? ". Secure" : "",
100	            static_cast<bool>(compression) ? "" : ". Uncompressed");
101	
102	        auto addresses = DNSResolver::instance().resolveAddressList(host, port);
103	        const auto & connection_timeout = static_cast<bool>(secure) ? timeouts.secure_connection_timeout : timeouts.connection_timeout;
104	
105	        for (auto it = addresses.begin(); it != addresses.end();)
106	        {
107	            if (connected)
108	                disconnect();
109	
110	            if (static_cast<bool>(secure))
111	            {
112	#if USE_SSL
113	                socket = std::make_unique<Poco::Net::SecureStreamSocket>();
114	
115	                /// we resolve the ip when we open SecureStreamSocket, so to make Server Name Indication (SNI)
116	                /// work we need to pass host name separately. It will be send into TLS Hello packet to let
117	                /// the server know which host we want to talk with (single IP can process requests for multiple hosts using SNI).
118	                static_cast<Poco::Net::SecureStreamSocket*>(socket.get())->setPeerHostName(host);
119	#else
120	                throw Exception{"tcp_secure protocol is disabled because poco library was built without NetSSL support.", ErrorCodes::SUPPORT_IS_DISABLED};
121	#endif
122	            }
123	            else
124	            {
125	                socket = std::make_unique<Poco::Net::StreamSocket>();
126	            }
127	
128	            try
129	            {
130	                socket->connect(*it, connection_timeout);
131	                current_resolved_address = *it;
132	                break;
133	            }
134	            catch (Poco::Net::NetException &)
135	            {
136	                if (++it == addresses.end())
137	                    throw;
138	                continue;
139	            }
140	            catch (Poco::TimeoutException &)
141	            {
142	                if (++it == addresses.end())
143	                    throw;
144	                continue;
145	            }
146	        }
147	
148	        socket->setReceiveTimeout(timeouts.receive_timeout);
149	        socket->setSendTimeout(timeouts.send_timeout);
150	        socket->setNoDelay(true);
151	        if (timeouts.tcp_keep_alive_timeout.totalSeconds())
152	        {
153	            socket->setKeepAlive(true);
154	            socket->setOption(IPPROTO_TCP,
155	#if defined(TCP_KEEPALIVE)
156	                TCP_KEEPALIVE
157	#else
158	                TCP_KEEPIDLE  // __APPLE__
159	#endif
160	                , timeouts.tcp_keep_alive_timeout);
161	        }
162	
163	        in = std::make_shared<ReadBufferFromPocoSocket>(*socket);
164	        in->setAsyncCallback(std::move(async_callback));
165	
166	        out = std::make_shared<WriteBufferFromPocoSocket>(*socket);
167	
168	        connected = true;
169	
170	        sendHello();
171	        receiveHello();
172	
173	        LOG_TRACE(log_wrapper.get(), "Connected to {} server version {}.{}.{}.",
174	            server_name, server_version_major, server_version_minor, server_version_patch);
175	    }
176	    catch (Poco::Net::NetException & e)
177	    {
178	        disconnect();
179	
180	        /// Add server address to exception. Also Exception will remember stack trace. It's a pity that more precise exception type is lost.
181	        throw NetException(e.displayText() + " (" + getDescription() + ")", ErrorCodes::NETWORK_ERROR);
182	    }
183	    catch (Poco::TimeoutException & e)
184	    {
185	        disconnect();
186	
187	        /// Add server address to exception. Also Exception will remember stack trace. It's a pity that more precise exception type is lost.
188	        /// This exception can only be thrown from socket->connect(), so add information about connection timeout.
189	        const auto & connection_timeout = static_cast<bool>(secure) ? timeouts.secure_connection_timeout : timeouts.connection_timeout;
190	        throw NetException(
191	            ErrorCodes::SOCKET_TIMEOUT,
192	            "{} ({}, connection timeout {} ms)",
193	            e.displayText(),
