76	Field QueryFuzzer::fuzzField(Field field)
77	{
78	    const auto type = field.getType();
79	
80	    int type_index = -1;
81	
82	    if (type == Field::Types::Int64
83	        || type == Field::Types::UInt64)
84	    {
85	        type_index = 0;
86	    }
87	    else if (type == Field::Types::Float64)
88	    {
89	        type_index = 1;
90	    }
91	    else if (type == Field::Types::Decimal32
92	             || type == Field::Types::Decimal64
93	             || type == Field::Types::Decimal128)
94	    {
95	        type_index = 2;
96	    }
97	
98	    if (fuzz_rand() % 20 == 0)
99	    {
100	        return Null{};
101	    }
102	
103	    if (type_index >= 0)
104	    {
105	        if (fuzz_rand() % 20 == 0)
106	        {
107	            // Change type sometimes, but not often, because it mostly leads to
108	            // boring errors.
109	            type_index = fuzz_rand() % 3;
110	        }
111	        return getRandomField(type_index);
112	    }
113	
114	    if (type == Field::Types::String)
115	    {
116	        auto & str = field.get<std::string>();
117	        UInt64 action = fuzz_rand() % 10;
118	        switch (action)
119	        {
120	        case 0:
121	            str = "";
122	            break;
123	        case 1:
124	            str = str + str;
125	            break;
126	        case 2:
127	            str = str + str + str + str;
128	            break;
129	        case 4:
130	            if (!str.empty())
131	            {
132	                str[fuzz_rand() % str.size()] = '\0';
133	            }
134	            break;
135	        default:
136	            // Do nothing
137	            break;
138	        }
139	    }
140	    else if (type == Field::Types::Array || type == Field::Types::Tuple)
141	    {
142	        auto & arr = field.reinterpret<FieldVector>();
143	
144	        if (fuzz_rand() % 5 == 0 && !arr.empty())
145	        {
146	            size_t pos = fuzz_rand() % arr.size();
147	            arr.erase(arr.begin() + pos);
148	            std::cerr << "erased\n";
149	        }
150	
151	        if (fuzz_rand() % 5 == 0)
152	        {
153	            if (!arr.empty())
154	            {
155	                size_t pos = fuzz_rand() % arr.size();
156	                arr.insert(arr.begin() + pos, fuzzField(arr[pos]));
157	                std::cerr << fmt::format("inserted (pos {})\n", pos);
158	            }
159	            else
160	            {
161	                arr.insert(arr.begin(), getRandomField(0));
162	                std::cerr << "inserted (0)\n";
163	            }
164	
165	        }
166	
167	        for (auto & element : arr)
168	        {
169	            element = fuzzField(element);
170	        }
171	    }
172	
173	    return field;
174	}
