544	 * TODO: we just stop remembering new parts after our corpus reaches certain size.
545	 * This is boring, should implement a random replacement of existing parst with
546	 * small probability. Do this after we add this fuzzer to CI and fix all the
547	 * problems it can routinely find even in this boring version.
548	 */
549	void QueryFuzzer::collectFuzzInfoMain(ASTPtr ast)
550	{
551	    collectFuzzInfoRecurse(ast);
552	
553	    aliases.clear();
554	    for (const auto & alias : aliases_set)
555	    {
556	        aliases.push_back(alias);
557	    }
558	
559	    column_like.clear();
560	    for (const auto & [name, value] : column_like_map)
561	    {
562	        column_like.push_back(value);
563	    }
564	
565	    table_like.clear();
566	    for (const auto & [name, value] : table_like_map)
567	    {
568	        table_like.push_back(value);
569	    }
570	}
571	
572	void QueryFuzzer::addTableLike(ASTPtr ast)
573	{
574	    if (table_like_map.size() > 1000)
575	    {
576	        table_like_map.clear();
577	    }
578	
579	    const auto name = ast->formatForErrorMessage();
580	    if (name.size() < 200)
581	    {
582	        table_like_map.insert({name, ast});
583	    }
584	}
585	
586	void QueryFuzzer::addColumnLike(ASTPtr ast)
587	{
588	    if (column_like_map.size() > 1000)
589	    {
590	        column_like_map.clear();
591	    }
592	
593	    const auto name = ast->formatForErrorMessage();
594	    if (name == "Null")
595	    {
596	        // The `Null` identifier from FORMAT Null clause. We don't quote it
597	        // properly when formatting the AST, and while the resulting query
598	        // technically works, it has non-standard case for Null (the standard
599	        // is NULL), so it breaks the query formatting idempotence check.
600	        // Just plug this particular case for now.
601	        return;
602	    }
603	    if (name.size() < 200)
604	    {
605	        column_like_map.insert({name, ast});
606	    }
607	}
608	
609	void QueryFuzzer::collectFuzzInfoRecurse(ASTPtr ast)
610	{
611	    if (auto * impl = dynamic_cast<ASTWithAlias *>(ast.get()))
612	    {
613	        if (aliases_set.size() > 1000)
614	        {
615	            aliases_set.clear();
616	        }
617	
618	        aliases_set.insert(impl->alias);
619	    }
620	
621	    if (typeid_cast<ASTLiteral *>(ast.get()))
622	    {
623	        addColumnLike(ast);
624	    }
625	    else if (typeid_cast<ASTIdentifier *>(ast.get()))
626	    {
627	        addColumnLike(ast);
628	    }
629	    else if (typeid_cast<ASTFunction *>(ast.get()))
630	    {
631	        addColumnLike(ast);
632	    }
633	    else if (typeid_cast<ASTTableExpression *>(ast.get()))
634	    {
635	        addTableLike(ast);
636	    }
637	    else if (typeid_cast<ASTSubquery *>(ast.get()))
638	    {
639	        addTableLike(ast);
640	    }
641	
642	    for (const auto & child : ast->children)
643	    {
644	        collectFuzzInfoRecurse(child);
645	    }
646	}
647	
648	void QueryFuzzer::fuzzMain(ASTPtr & ast)
649	{
650	    current_ast_depth = 0;
651	    debug_visited_nodes.clear();
652	    debug_top_ast = &ast;
653	
654	    collectFuzzInfoMain(ast);
655	    fuzz(ast);
656	
657	    std::cout << std::endl;
658	    WriteBufferFromOStream ast_buf(std::cout, 4096);
659	    formatAST(*ast, ast_buf, false /*highlight*/);
660	    ast_buf.next();
661	    std::cout << std::endl << std::endl;
662	}
663	
