181	void StorageSetOrJoinBase::restore()
182	{
183	    if (!disk->exists(fs::path(path) / "tmp/"))
184	    {
185	        disk->createDirectories(fs::path(path) / "tmp/");
186	        return;
187	    }
188	
189	    static const char * file_suffix = ".bin";
190	    static const auto file_suffix_size = strlen(".bin");
191	
192	    for (auto dir_it{disk->iterateDirectory(path)}; dir_it->isValid(); dir_it->next())
193	    {
194	        const auto & name = dir_it->name();
195	        const auto & file_path = dir_it->path();
196	
197	        if (disk->isFile(file_path)
198	            && endsWith(name, file_suffix)
199	            && disk->getFileSize(file_path) > 0)
200	        {
201	            /// Calculate the maximum number of available files with a backup to add the following files with large numbers.
202	            UInt64 file_num = parse<UInt64>(name.substr(0, name.size() - file_suffix_size));
203	            if (file_num > increment)
204	                increment = file_num;
205	
206	            restoreFromFile(dir_it->path());
207	        }
208	    }
209	}
