401	void ClientBase::onData(Block & block, ASTPtr parsed_query)
402	{
403	    if (!block)
404	        return;
405	
406	    processed_rows += block.rows();
407	
408	    /// Even if all blocks are empty, we still need to initialize the output stream to write empty resultset.
409	    initOutputFormat(block, parsed_query);
410	
411	    /// The header block containing zero rows was used to initialize
412	    /// output_format, do not output it.
413	    /// Also do not output too much data if we're fuzzing.
414	    if (block.rows() == 0 || (query_fuzzer_runs != 0 && processed_rows >= 100))
415	        return;
416	
417	    /// If results are written INTO OUTFILE, we can avoid clearing progress to avoid flicker.
418	    if (need_render_progress && (stdout_is_a_tty || is_interactive) && !select_into_file)
419	        progress_indication.clearProgressOutput();
420	
421	    try
422	    {
423	        output_format->write(materializeBlock(block));
424	        written_first_block = true;
425	    }
426	    catch (const Exception &)
427	    {
428	        /// Catch client errors like NO_ROW_DELIMITER
429	        throw LocalFormatError(getCurrentExceptionMessage(print_stack_trace), getCurrentExceptionCode());
430	    }
431	
432	    /// Received data block is immediately displayed to the user.
433	    output_format->flush();
434	
435	    /// Restore progress bar after data block.
436	    if (need_render_progress && (stdout_is_a_tty || is_interactive))
437	    {
438	        if (select_into_file)
439	            std::cerr << "\r";
440	        progress_indication.writeProgress();
441	    }
442	}
