7513	std::pair<bool, NameSet> StorageReplicatedMergeTree::unlockSharedDataByID(
7514	        String part_id, const String & table_uuid, const String & part_name,
7515	        const String & replica_name_, std::string disk_type, zkutil::ZooKeeperPtr zookeeper_ptr, const MergeTreeSettings & settings,
7516	        Poco::Logger * logger, const String & zookeeper_path_old)
7517	{
7518	    boost::replace_all(part_id, "/", "_");
7519	
7520	    Strings zc_zookeeper_paths = getZeroCopyPartPath(settings, disk_type, table_uuid, part_name, zookeeper_path_old);
7521	
7522	    bool part_has_no_more_locks = true;
7523	    NameSet files_not_to_remove;
7524	
7525	    for (const auto & zc_zookeeper_path : zc_zookeeper_paths)
7526	    {
7527	        String files_not_to_remove_str;
7528	        zookeeper_ptr->tryGet(zc_zookeeper_path, files_not_to_remove_str);
7529	
7530	        files_not_to_remove.clear();
7531	        if (!files_not_to_remove_str.empty())
7532	            boost::split(files_not_to_remove, files_not_to_remove_str, boost::is_any_of("\n "));
7533	
7534	        String zookeeper_part_uniq_node = fs::path(zc_zookeeper_path) / part_id;
7535	
7536	        /// Delete our replica node for part from zookeeper (we are not interested in it anymore)
7537	        String zookeeper_part_replica_node = fs::path(zookeeper_part_uniq_node) / replica_name_;
7538	
7539	        LOG_TRACE(logger, "Remove zookeeper lock {} for part {}", zookeeper_part_replica_node, part_name);
7540	
7541	        if (auto ec = zookeeper_ptr->tryRemove(zookeeper_part_replica_node); ec != Coordination::Error::ZOK && ec != Coordination::Error::ZNONODE)
7542	        {
7543	            throw zkutil::KeeperException(ec, zookeeper_part_replica_node);
7544	        }
7545	
7546	        /// Check, maybe we were the last replica and can remove part forever
7547	        Strings children;
7548	        zookeeper_ptr->tryGetChildren(zookeeper_part_uniq_node, children);
7549	
7550	        if (!children.empty())
7551	        {
7552	            LOG_TRACE(logger, "Found {} ({}) zookeper locks for {}", zookeeper_part_uniq_node, children.size(), fmt::join(children, ", "));
7553	            part_has_no_more_locks = false;
7554	            continue;
7555	        }
7556	
7557	        auto error_code = zookeeper_ptr->tryRemove(zookeeper_part_uniq_node);
7558	
7559	        if (error_code == Coordination::Error::ZOK)
7560	        {
7561	            LOG_TRACE(logger, "Removed last parent zookeeper lock {} for part {} with id {}", zookeeper_part_uniq_node, part_name, part_id);
7562	        }
7563	        else if (error_code == Coordination::Error::ZNOTEMPTY)
7564	        {
7565	            LOG_TRACE(logger, "Cannot remove last parent zookeeper lock {} for part {} with id {}, another replica locked part concurrently", zookeeper_part_uniq_node, part_name, part_id);
7566	        }
7567	        else if (error_code == Coordination::Error::ZNONODE)
7568	        {
7569	            LOG_TRACE(logger, "Node with parent zookeeper lock {} for part {} with id {} doesn't exist", zookeeper_part_uniq_node, part_name, part_id);
7570	        }
7571	        else
7572	        {
7573	            throw zkutil::KeeperException(error_code, zookeeper_part_uniq_node);
7574	        }
7575	
7576	
7577	        /// Even when we have lock with same part name, but with different uniq, we can remove files on S3
7578	        children.clear();
7579	        String zookeeper_part_node = fs::path(zookeeper_part_uniq_node).parent_path();
7580	        zookeeper_ptr->tryGetChildren(zookeeper_part_node, children);
7581	
7582	        if (children.empty())
7583	        {
7584	            /// Cleanup after last uniq removing
7585	            error_code = zookeeper_ptr->tryRemove(zookeeper_part_node);
7586	
7587	            if (error_code == Coordination::Error::ZOK)
7588	            {
7589	                LOG_TRACE(logger, "Removed last parent zookeeper lock {} for part {} (part is finally unlocked)", zookeeper_part_uniq_node, part_name);
7590	            }
7591	            else if (error_code == Coordination::Error::ZNOTEMPTY)
7592	            {
7593	                LOG_TRACE(logger, "Cannot remove last parent zookeeper lock {} for part {}, another replica locked part concurrently", zookeeper_part_uniq_node, part_name);
7594	            }
7595	            else if (error_code == Coordination::Error::ZNONODE)
7596	            {
7597	                LOG_TRACE(logger, "Node with parent zookeeper lock {} for part {} doesn't exist (part was unlocked before)", zookeeper_part_uniq_node, part_name);
7598	            }
7599	            else
7600	            {
7601	                throw zkutil::KeeperException(error_code, zookeeper_part_uniq_node);
7602	            }
7603	        }
7604	        else
7605	        {
7606	            LOG_TRACE(logger, "Can't remove parent zookeeper lock {} for part {}, because children {} ({}) were concurrently created",
7607	                      zookeeper_part_node, part_name, children.size(), fmt::join(children, ", "));
7608	        }
7609	    }
7610	
7611	    return std::make_pair(part_has_no_more_locks, files_not_to_remove);
7612	}
