233	    size_t entries_count = 0;
234	    size_t usable_count = 0;
235	    size_t up_to_date_count = 0;
236	    size_t failed_pools_count = 0;
237	
238	    /// At exit update shared error counts with error counts occurred during this call.
239	    SCOPE_EXIT(
240	    {
241	        updateSharedErrorCounts(shuffled_pools);
242	    });
243	
244	    std::string fail_messages;
245	    bool finished = false;
246	    while (!finished)
247	    {
248	        for (size_t i = 0; i < shuffled_pools.size(); ++i)
249	        {
250	            if (up_to_date_count >= max_entries /// Already enough good entries.
251	                || entries_count + failed_pools_count >= nested_pools.size()) /// No more good entries will be produced.
252	            {
253	                finished = true;
254	                break;
255	            }
256	
257	            ShuffledPool & shuffled_pool = shuffled_pools[i];
258	            TryResult & result = try_results[i];
259	            if (max_tries && (shuffled_pool.error_count >= max_tries || !result.entry.isNull()))
260	                continue;
261	
262	            std::string fail_message;
263	            result = try_get_entry(*shuffled_pool.pool, fail_message);
264	
265	            if (!fail_message.empty())
266	                fail_messages += fail_message + '\n';
267	
268	            if (!result.entry.isNull())
269	            {
270	                ++entries_count;
271	                if (result.is_usable)
272	                {
273	                    ++usable_count;
274	                    if (result.is_up_to_date)
275	                        ++up_to_date_count;
276	                }
277	            }
278	            else
279	            {
280	                LOG_WARNING(log, "Connection failed at try №{}, reason: {}", (shuffled_pool.error_count + 1), fail_message);
281	                ProfileEvents::increment(ProfileEvents::DistributedConnectionFailTry);
282	
283	                shuffled_pool.error_count = std::min(max_error_cap, shuffled_pool.error_count + 1);
284	
285	                if (shuffled_pool.error_count >= max_tries)
286	                {
287	                    ++failed_pools_count;
288	                    ProfileEvents::increment(ProfileEvents::DistributedConnectionFailAtAll);
289	                }
290	            }
291	        }
292	    }
293	
294	    if (usable_count < min_entries)
295	        throw DB::NetException(
296	                "All connection tries failed. Log: \n\n" + fail_messages + "\n",
297	                DB::ErrorCodes::ALL_CONNECTION_TRIES_FAILED);
298	
299	    std::erase_if(try_results, [](const TryResult & r) { return r.entry.isNull() || !r.is_usable; });
300	
301	    /// Sort so that preferred items are near the beginning.
302	    std::stable_sort(
303	            try_results.begin(), try_results.end(),
304	            [](const TryResult & left, const TryResult & right)
305	            {
306	                return std::forward_as_tuple(!left.is_up_to_date, left.staleness)
307	                    < std::forward_as_tuple(!right.is_up_to_date, right.staleness);
308	            });
309	
310	    if (fallback_to_stale_replicas)
311	    {
312	        /// There is not enough up-to-date entries but we are allowed to return stale entries.
313	        /// Gather all up-to-date ones and least-bad stale ones.
314	
315	        size_t size = std::min(try_results.size(), max_entries);
316	        try_results.resize(size);
317	    }
318	    else if (up_to_date_count >= min_entries)
319	    {
320	        /// There is enough up-to-date entries.
321	        try_results.resize(up_to_date_count);
322	    }
323	    else
324	        throw DB::Exception(
325	                "Could not find enough connections to up-to-date replicas. Got: " + std::to_string(up_to_date_count)
326	                + ", needed: " + std::to_string(min_entries),
327	                DB::ErrorCodes::ALL_REPLICAS_ARE_STALE);
328	
329	    return try_results;

545	    if (!remote_fs_metadata.empty())
546	    {
547	        if (!try_zero_copy)
548	            throw Exception("Got unexpected 'remote_fs_metadata' cookie", ErrorCodes::LOGICAL_ERROR);
549	        if (std::find(capability.begin(), capability.end(), remote_fs_metadata) == capability.end())
550	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Got 'remote_fs_metadata' cookie {}, expect one from {}", remote_fs_metadata, fmt::join(capability, ", "));
551	        if (server_protocol_version < REPLICATION_PROTOCOL_VERSION_WITH_PARTS_ZERO_COPY)
552	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Got 'remote_fs_metadata' cookie with old protocol version {}", server_protocol_version);
553	        if (part_type == "InMemory")
554	            throw Exception("Got 'remote_fs_metadata' cookie for in-memory part", ErrorCodes::INCORRECT_PART_TYPE);
555	
556	        try
557	        {
558	            return downloadPartToDiskRemoteMeta(part_name, replica_path, to_detached, tmp_prefix_, disk, *in, throttler);
559	        }
560	        catch (const Exception & e)
561	        {
562	            if (e.code() != ErrorCodes::S3_ERROR && e.code() != ErrorCodes::ZERO_COPY_REPLICATION_ERROR)
563	                throw;
564	
565	            LOG_WARNING(log, fmt::runtime(e.message() + " Will retry fetching part without zero-copy."));
566	
567	            /// It's important to release session from HTTP pool. Otherwise it's possible to get deadlock
568	            /// on http pool.
569	            try
570	            {
571	                in.reset();
572	            }
573	            catch (...)
574	            {
575	                tryLogCurrentException(log);
576	            }
577	
578	            /// Try again but without zero-copy
579	            return fetchPart(metadata_snapshot, context, part_name, replica_path, host, port, timeouts,
580	                user, password, interserver_scheme, throttler, to_detached, tmp_prefix_, nullptr, false, disk);
581	        }
582	    }
583	
584	    auto storage_id = data.getStorageID();
585	    String new_part_path = part_type == "InMemory" ? "memory" : fs::path(data.getFullPathOnDisk(disk)) / part_name / "";
586	    auto entry = data.getContext()->getReplicatedFetchList().insert(
587	        storage_id.getDatabaseName(), storage_id.getTableName(),
588	        part_info.partition_id, part_name, new_part_path,
589	        replica_path, uri, to_detached, sum_files_size);
590	
591	    in->setNextCallback(ReplicatedFetchReadCallback(*entry));
592	
593	    size_t projections = 0;
594	    if (server_protocol_version >= REPLICATION_PROTOCOL_VERSION_WITH_PARTS_PROJECTION)
595	        readBinary(projections, *in);
596	
597	    MergeTreeData::DataPart::Checksums checksums;
598	    return part_type == "InMemory"
599	        ? downloadPartToMemory(part_name, part_uuid, metadata_snapshot, context, disk, *in, projections, throttler)
600	        : downloadPartToDisk(part_name, replica_path, to_detached, tmp_prefix_, sync, disk, *in, projections, checksums, throttler);
601	}
