603	MergeTreeData::MutableDataPartPtr Fetcher::downloadPartToMemory(
604	    const String & part_name,
605	    const UUID & part_uuid,
606	    const StorageMetadataPtr & metadata_snapshot,
607	    ContextPtr context,
608	    DiskPtr disk,
609	    PooledReadWriteBufferFromHTTP & in,
610	    size_t projections,
611	    ThrottlerPtr throttler)
612	{
613	    auto volume = std::make_shared<SingleDiskVolume>("volume_" + part_name, disk, 0);
614	
615	    auto data_part_storage = std::make_shared<DataPartStorageOnDisk>(
616	        volume,
617	        data.getRelativeDataPath(),
618	        part_name);
619	
620	    auto data_part_storage_builder = std::make_shared<DataPartStorageBuilderOnDisk>(
621	        volume,
622	        data.getRelativeDataPath(),
623	        part_name);
624	
625	    MergeTreeData::MutableDataPartPtr new_data_part =
626	        std::make_shared<MergeTreeDataPartInMemory>(data, part_name, data_part_storage);
627	    new_data_part->version.setCreationTID(Tx::PrehistoricTID, nullptr);
628	
629	    for (auto i = 0ul; i < projections; ++i)
630	    {
631	        String projection_name;
632	        readStringBinary(projection_name, in);
633	        MergeTreeData::DataPart::Checksums checksums;
634	        if (!checksums.read(in))
635	            throw Exception("Cannot deserialize checksums", ErrorCodes::CORRUPTED_DATA);
636	
637	        NativeReader block_in(in, 0);
638	        auto block = block_in.read();
639	        throttler->add(block.bytes());
640	
641	        auto projection_part_storage = data_part_storage->getProjection(projection_name + ".proj");
642	        auto projection_part_storage_builder = data_part_storage_builder->getProjection(projection_name + ".proj");
643	
644	        MergeTreePartInfo new_part_info("all", 0, 0, 0);
645	        MergeTreeData::MutableDataPartPtr new_projection_part =
646	            std::make_shared<MergeTreeDataPartInMemory>(data, projection_name, new_part_info, projection_part_storage, new_data_part.get());
647	
648	        new_projection_part->is_temp = false;
649	        new_projection_part->setColumns(block.getNamesAndTypesList());
650	        MergeTreePartition partition{};
651	        new_projection_part->partition = std::move(partition);
652	        new_projection_part->minmax_idx = std::make_shared<IMergeTreeDataPart::MinMaxIndex>();
653	
654	        MergedBlockOutputStream part_out(
655	            new_projection_part,
656	            projection_part_storage_builder,
657	            metadata_snapshot->projections.get(projection_name).metadata,
658	            block.getNamesAndTypesList(),
659	            {},
660	            CompressionCodecFactory::instance().get("NONE", {}),
661	            NO_TRANSACTION_PTR);
662	
663	        part_out.write(block);
664	        part_out.finalizePart(new_projection_part, false);
665	        new_projection_part->checksums.checkEqual(checksums, /* have_uncompressed = */ true);
666	        new_data_part->addProjectionPart(projection_name, std::move(new_projection_part));
667	    }
668	
669	    MergeTreeData::DataPart::Checksums checksums;
670	    if (!checksums.read(in))
671	        throw Exception("Cannot deserialize checksums", ErrorCodes::CORRUPTED_DATA);
672	
673	    NativeReader block_in(in, 0);
674	    auto block = block_in.read();
675	    throttler->add(block.bytes());
676	
677	    new_data_part->uuid = part_uuid;
678	    new_data_part->is_temp = true;
679	    new_data_part->setColumns(block.getNamesAndTypesList());
680	    new_data_part->minmax_idx->update(block, data.getMinMaxColumnsNames(metadata_snapshot->getPartitionKey()));
681	    new_data_part->partition.create(metadata_snapshot, block, 0, context);
682	
683	    MergedBlockOutputStream part_out(
684	        new_data_part, data_part_storage_builder, metadata_snapshot, block.getNamesAndTypesList(), {},
685	        CompressionCodecFactory::instance().get("NONE", {}), NO_TRANSACTION_PTR);
686	
687	    part_out.write(block);
688	    part_out.finalizePart(new_data_part, false);
689	    new_data_part->checksums.checkEqual(checksums, /* have_uncompressed = */ true);
690	
691	    return new_data_part;
692	}
