754	MergeTreeData::MutableDataPartPtr Fetcher::downloadPartToDisk(
755	    const String & part_name,
756	    const String & replica_path,
757	    bool to_detached,
758	    const String & tmp_prefix_,
759	    bool sync,
760	    DiskPtr disk,
761	    PooledReadWriteBufferFromHTTP & in,
762	    size_t projections,
763	    MergeTreeData::DataPart::Checksums & checksums,
764	    ThrottlerPtr throttler)
765	{
766	    static const String TMP_PREFIX = "tmp-fetch_";
767	    String tmp_prefix = tmp_prefix_.empty() ? TMP_PREFIX : tmp_prefix_;
768	
769	    /// We will remove directory if it's already exists. Make precautions.
770	    if (tmp_prefix.empty() //-V560
771	        || part_name.empty()
772	        || std::string::npos != tmp_prefix.find_first_of("/.")
773	        || std::string::npos != part_name.find_first_of("/."))
774	        throw Exception("Logical error: tmp_prefix and part_name cannot be empty or contain '.' or '/' characters.", ErrorCodes::LOGICAL_ERROR);
775	
776	    String part_dir = tmp_prefix + part_name;
777	    String part_relative_path = data.getRelativeDataPath() + String(to_detached ? "detached/" : "");
778	
779	    auto volume = std::make_shared<SingleDiskVolume>("volume_" + part_name, disk, 0);
780	
781	    auto data_part_storage = std::make_shared<DataPartStorageOnDisk>(
782	        volume,
783	        part_relative_path,
784	        part_dir);
785	
786	    DataPartStorageBuilderPtr data_part_storage_builder = std::make_shared<DataPartStorageBuilderOnDisk>(
787	        volume,
788	        part_relative_path,
789	        part_dir);
790	
791	    if (data_part_storage_builder->exists())
792	    {
793	        LOG_WARNING(log, "Directory {} already exists, probably result of a failed fetch. Will remove it before fetching part.",
794	            data_part_storage_builder->getFullPath());
795	        data_part_storage_builder->removeRecursive();
796	    }
797	
798	    data_part_storage_builder->createDirectories();
799	
800	    SyncGuardPtr sync_guard;
801	    if (data.getSettings()->fsync_part_directory)
802	        sync_guard = disk->getDirectorySyncGuard(data_part_storage->getRelativePath());
803	
804	    CurrentMetrics::Increment metric_increment{CurrentMetrics::ReplicatedFetch};
805	
806	    for (auto i = 0ul; i < projections; ++i)
807	    {
808	        String projection_name;
809	        readStringBinary(projection_name, in);
810	        MergeTreeData::DataPart::Checksums projection_checksum;
811	
812	        auto projection_part_storage = data_part_storage->getProjection(projection_name + ".proj");
813	        auto projection_part_storage_builder = data_part_storage_builder->getProjection(projection_name + ".proj");
814	
815	        projection_part_storage_builder->createDirectories();
816	        downloadBaseOrProjectionPartToDisk(
817	            replica_path, projection_part_storage_builder, sync, in, projection_checksum, throttler);
818	        checksums.addFile(
819	            projection_name + ".proj", projection_checksum.getTotalSizeOnDisk(), projection_checksum.getTotalChecksumUInt128());
820	    }
821	
822	    // Download the base part
823	    downloadBaseOrProjectionPartToDisk(replica_path, data_part_storage_builder, sync, in, checksums, throttler);
824	
825	    assertEOF(in);
826	    MergeTreeData::MutableDataPartPtr new_data_part = data.createPart(part_name, data_part_storage);
827	    new_data_part->version.setCreationTID(Tx::PrehistoricTID, nullptr);
828	    new_data_part->is_temp = true;
829	    new_data_part->modification_time = time(nullptr);
830	    new_data_part->loadColumnsChecksumsIndexes(true, false);
831	    new_data_part->checksums.checkEqual(checksums, false);
832	    return new_data_part;
833	}
