835	MergeTreeData::MutableDataPartPtr Fetcher::downloadPartToDiskRemoteMeta(
836	    const String & part_name,
837	    const String & replica_path,
838	    bool to_detached,
839	    const String & tmp_prefix_,
840	    DiskPtr disk,
841	    PooledReadWriteBufferFromHTTP & in,
842	    ThrottlerPtr throttler)
843	{
844	    String part_id;
845	    readStringBinary(part_id, in);
846	
847	    if (!disk->supportZeroCopyReplication() || !disk->checkUniqueId(part_id))
848	    {
849	        throw Exception(ErrorCodes::ZERO_COPY_REPLICATION_ERROR, "Part {} unique id {} doesn't exist on {}.", part_name, part_id, disk->getName());
850	    }
851	
852	    LOG_DEBUG(log, "Downloading Part {} unique id {} metadata onto disk {}.",
853	        part_name, part_id, disk->getName());
854	
855	    data.lockSharedDataTemporary(part_name, part_id, disk);
856	
857	    static const String TMP_PREFIX = "tmp-fetch_";
858	    String tmp_prefix = tmp_prefix_.empty() ? TMP_PREFIX : tmp_prefix_;
859	
860	    String part_dir = tmp_prefix + part_name;
861	    String part_relative_path = data.getRelativeDataPath() + String(to_detached ? "detached/" : "");
862	
863	    auto volume = std::make_shared<SingleDiskVolume>("volume_" + part_name, disk);
864	
865	    auto data_part_storage = std::make_shared<DataPartStorageOnDisk>(
866	        volume,
867	        part_relative_path,
868	        part_dir);
869	
870	    DataPartStorageBuilderPtr data_part_storage_builder = std::make_shared<DataPartStorageBuilderOnDisk>(
871	        volume,
872	        part_relative_path,
873	        part_dir);
874	
875	    if (data_part_storage->exists())
876	        throw Exception(ErrorCodes::DIRECTORY_ALREADY_EXISTS, "Directory {} already exists.", data_part_storage->getFullPath());
877	
878	    CurrentMetrics::Increment metric_increment{CurrentMetrics::ReplicatedFetch};
879	
880	    volume->getDisk()->createDirectories(data_part_storage->getFullPath());
881	
882	    size_t files;
883	    readBinary(files, in);
884	
885	    for (size_t i = 0; i < files; ++i)
886	    {
887	        String file_name;
888	        UInt64 file_size;
889	
890	        readStringBinary(file_name, in);
891	        readBinary(file_size, in);
892	
893	        String metadata_file = fs::path(data_part_storage->getFullPath()) / file_name;
894	
895	        {
896	            auto file_out = std::make_unique<WriteBufferFromFile>(metadata_file, DBMS_DEFAULT_BUFFER_SIZE, -1, 0666, nullptr, 0);
897	
898	            HashingWriteBuffer hashing_out(*file_out);
899	
900	            copyDataWithThrottler(in, hashing_out, file_size, blocker.getCounter(), throttler);
901	
902	            if (blocker.isCancelled())
903	            {
904	                /// NOTE The is_cancelled flag also makes sense to check every time you read over the network,
905	                /// performing a poll with a not very large timeout.
906	                /// And now we check it only between read chunks (in the `copyData` function).
907	                data_part_storage_builder->removeSharedRecursive(true);
908	                data_part_storage_builder->commit();
909	                throw Exception("Fetching of part was cancelled", ErrorCodes::ABORTED);
910	            }
911	
912	            MergeTreeDataPartChecksum::uint128 expected_hash;
913	            readPODBinary(expected_hash, in);
914	
915	            if (expected_hash != hashing_out.getHash())
916	            {
917	                throw Exception(ErrorCodes::CHECKSUM_DOESNT_MATCH,
918	                    "Checksum mismatch for file {} transferred from {}",
919	                    metadata_file, replica_path);
920	            }
921	        }
922	    }
923	
924	    assertEOF(in);
925	
926	    data_part_storage_builder->commit();
927	
928	    MergeTreeData::MutableDataPartPtr new_data_part = data.createPart(part_name, data_part_storage);
929	    new_data_part->version.setCreationTID(Tx::PrehistoricTID, nullptr);
930	    new_data_part->is_temp = true;
931	    new_data_part->modification_time = time(nullptr);
932	    new_data_part->loadColumnsChecksumsIndexes(true, false);
933	
934	    data.lockSharedData(*new_data_part, /* replace_existing_lock = */ true, {});
935	
936	    LOG_DEBUG(log, "Download of part {} unique id {} metadata onto disk {} finished.",
937	        part_name, part_id, disk->getName());
938	
939	    return new_data_part;
940	}
941	
942	}
