22	inline bool HadoopSnappyDecoder::checkBufferLength(int max) const
23	{
24	    return buffer_length >= 0 && buffer_length < max;
25	}
26	
27	inline bool HadoopSnappyDecoder::checkAvailIn(size_t avail_in, int min)
28	{
29	    return avail_in >= static_cast<size_t>(min);
30	}
31	
32	inline void HadoopSnappyDecoder::copyToBuffer(size_t * avail_in, const char ** next_in)
33	{
34	    assert(*avail_in + buffer_length <= sizeof(buffer));
35	
36	    memcpy(buffer + buffer_length, *next_in, *avail_in);
37	
38	    buffer_length += *avail_in;
39	    *next_in += *avail_in;
40	    *avail_in = 0;
41	}
42	
43	
44	inline uint32_t HadoopSnappyDecoder::readLength(const char * in)
45	{
46	    uint32_t b1 = *(reinterpret_cast<const uint8_t *>(in));
47	    uint32_t b2 = *(reinterpret_cast<const uint8_t *>(in + 1));
48	    uint32_t b3 = *(reinterpret_cast<const uint8_t *>(in + 2));
49	    uint32_t b4 = *(reinterpret_cast<const uint8_t *>(in + 3));
50	    uint32_t res = ((b1 << 24) + (b2 << 16) + (b3 << 8) + b4);
51	    return res;
52	}
53	
54	
55	inline HadoopSnappyDecoder::Status HadoopSnappyDecoder::readLength(size_t * avail_in, const char ** next_in, int * length)
56	{
57	    char tmp[4] = {0};
58	
59	    if (!checkBufferLength(4))
60	        return Status::INVALID_INPUT;
61	    memcpy(tmp, buffer, buffer_length);
62	
63	    if (!checkAvailIn(*avail_in, 4 - buffer_length))
64	    {
65	        copyToBuffer(avail_in, next_in);
66	        return Status::NEEDS_MORE_INPUT;
67	    }
68	    memcpy(tmp + buffer_length, *next_in, 4 - buffer_length);
69	
70	    *avail_in -= 4 - buffer_length;
71	    *next_in += 4 - buffer_length;
72	    buffer_length = 0;
73	    *length = readLength(tmp);
74	    return Status::OK;
75	}
76	
77	inline HadoopSnappyDecoder::Status HadoopSnappyDecoder::readBlockLength(size_t * avail_in, const char ** next_in)
78	{
79	    if (block_length < 0)
80	    {
81	        return readLength(avail_in, next_in, &block_length);
82	    }
83	    return Status::OK;
84	}
85	
86	inline HadoopSnappyDecoder::Status HadoopSnappyDecoder::readCompressedLength(size_t * avail_in, const char ** next_in)
87	{
88	    if (compressed_length < 0)
89	    {
90	        auto status = readLength(avail_in, next_in, &compressed_length);
91	        if (unlikely(compressed_length > 0 && static_cast<size_t>(compressed_length) > sizeof(buffer)))
92	            throw Exception(ErrorCodes::SNAPPY_UNCOMPRESS_FAILED, "Too large snappy compressed block. buffer size: {}, compressed block size: {}", sizeof(buffer), compressed_length);
93	        return status;
94	    }
95	    return Status::OK;
96	}
97	
98	inline HadoopSnappyDecoder::Status
99	HadoopSnappyDecoder::readCompressedData(size_t * avail_in, const char ** next_in, size_t * avail_out, char ** next_out)
100	{
101	    if (!checkBufferLength(compressed_length))
102	        return Status::INVALID_INPUT;
103	
104	    if (!checkAvailIn(*avail_in, compressed_length - buffer_length))
105	    {
106	        copyToBuffer(avail_in, next_in);
107	        return Status::NEEDS_MORE_INPUT;
108	    }
109	
110	    const char * compressed = nullptr;
111	    if (buffer_length > 0)
112	    {
113	        compressed = buffer;
114	        memcpy(buffer + buffer_length, *next_in, compressed_length - buffer_length);
115	    }
116	    else
117	    {
118	        compressed = const_cast<char *>(*next_in);
119	    }
120	    size_t uncompressed_length = *avail_out;
121	    auto status = snappy_uncompress(compressed, compressed_length, *next_out, &uncompressed_length);
122	    if (status != SNAPPY_OK)
123	    {
124	        return Status(status);
125	    }
126	
127	    *avail_in -= compressed_length - buffer_length;
128	    *next_in += compressed_length - buffer_length;
129	    *avail_out -= uncompressed_length;
130	    *next_out += uncompressed_length;
131	
132	    total_uncompressed_length += uncompressed_length;
133	    compressed_length = -1;
134	    buffer_length = 0;
135	    return Status::OK;
136	}
137	
138	HadoopSnappyDecoder::Status HadoopSnappyDecoder::readBlock(size_t * avail_in, const char ** next_in, size_t * avail_out, char ** next_out)
139	{
140	    if (*avail_in == 0)
141	    {
142	        if (buffer_length == 0 && block_length < 0 && compressed_length < 0)
143	            return Status::OK;
144	        return Status::NEEDS_MORE_INPUT;
145	    }
146	
147	    HadoopSnappyDecoder::Status status = readBlockLength(avail_in, next_in);
148	    if (status != Status::OK)
149	        return status;
150	
151	    while (total_uncompressed_length < block_length)
152	    {
153	        status = readCompressedLength(avail_in, next_in);
154	        if (status != Status::OK)
155	            return status;
156	
157	        status = readCompressedData(avail_in, next_in, avail_out, next_out);
158	        if (status != Status::OK)
159	            return status;
160	    }
161	    if (total_uncompressed_length != block_length)
162	    {
163	        return Status::INVALID_INPUT;
164	    }
165	    return Status::OK;
166	}
167	
168	HadoopSnappyReadBuffer::HadoopSnappyReadBuffer(std::unique_ptr<ReadBuffer> in_, size_t buf_size, char * existing_memory, size_t alignment)
169	    : CompressedReadBufferWrapper(std::move(in_), buf_size, existing_memory, alignment)
170	    , decoder(std::make_unique<HadoopSnappyDecoder>())
171	    , in_available(0)
172	    , in_data(nullptr)
173	    , out_capacity(0)
174	    , out_data(nullptr)
175	    , eof(false)
176	{
177	}
178	
179	HadoopSnappyReadBuffer::~HadoopSnappyReadBuffer() = default;
180	
181	bool HadoopSnappyReadBuffer::nextImpl()
182	{
183	    if (eof)
184	        return false;
185	
186	    if (!in_available)
187	    {
188	        in->nextIfAtEnd();
189	        in_available = in->buffer().end() - in->position();
190	        in_data = in->position();
191	    }
192	
193	    if (decoder->result == Status::NEEDS_MORE_INPUT && (!in_available || in->eof()))
194	    {
195	        throw Exception(String("hadoop snappy decode error:") + statusToString(decoder->result), ErrorCodes::SNAPPY_UNCOMPRESS_FAILED);
196	    }
197	
198	    out_capacity = internal_buffer.size();
199	    out_data = internal_buffer.begin();
200	    decoder->result = decoder->readBlock(&in_available, &in_data, &out_capacity, &out_data);
201	
202	    in->position() = in->buffer().end() - in_available;
203	    working_buffer.resize(internal_buffer.size() - out_capacity);
204	
205	    if (decoder->result == Status::OK)
206	    {
207	        decoder->reset();
208	        if (in->eof())
209	        {
210	            eof = true;
211	            return !working_buffer.empty();
212	        }
213	        return true;
214	    }
215	    else if (decoder->result == Status::INVALID_INPUT || decoder->result == Status::BUFFER_TOO_SMALL)
216	    {
217	        throw Exception(String("hadoop snappy decode error:") + statusToString(decoder->result), ErrorCodes::SNAPPY_UNCOMPRESS_FAILED);
218	    }
219	    return true;
220	}
221	
222	}
