111	    class Action
112	    {
113	    public:
114	        using Func = void (*)(char *, Time, const DateLUTImpl &);
115	
116	        Func func;
117	        size_t shift;
118	
119	        explicit Action(Func func_, size_t shift_ = 0) : func(func_), shift(shift_) {}
