258	std::unique_ptr<ReadBuffer> ReadBufferFromS3::initialize()
259	{
260	    Aws::S3::Model::GetObjectRequest req;
261	    req.SetBucket(bucket);
262	    req.SetKey(key);
263	    if (!version_id.empty())
264	    {
265	        req.SetVersionId(version_id);
266	    }
267	
268	    /**
269	     * If remote_filesystem_read_method = 'threadpool', then for MergeTree family tables
270	     * exact byte ranges to read are always passed here.
271	     */
272	    if (read_until_position)
273	    {
274	        if (offset >= read_until_position)
275	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read beyond right offset ({} > {})", offset, read_until_position - 1);
276	
277	        req.SetRange(fmt::format("bytes={}-{}", offset, read_until_position - 1));
278	        LOG_TEST(
279	            log,
280	            "Read S3 object. Bucket: {}, Key: {}, Version: {}, Range: {}-{}",
281	            bucket,
282	            key,
283	            version_id.empty() ? "Latest" : version_id,
284	            offset,
285	            read_until_position - 1);
286	    }
287	    else
288	    {
289	        if (offset)
290	            req.SetRange(fmt::format("bytes={}-", offset));
291	        LOG_TEST(
292	            log,
293	            "Read S3 object. Bucket: {}, Key: {}, Version: {}, Offset: {}",
294	            bucket,
295	            key,
296	            version_id.empty() ? "Latest" : version_id,
297	            offset);
298	    }
299	
300	    Aws::S3::Model::GetObjectOutcome outcome = client_ptr->GetObject(req);
301	
302	    if (outcome.IsSuccess())
303	    {
304	        read_result = outcome.GetResultWithOwnership();
305	        size_t buffer_size = use_external_buffer ? 0 : read_settings.remote_fs_buffer_size;
306	        return std::make_unique<ReadBufferFromIStream>(read_result.GetBody(), buffer_size);
307	    }
308	    else
309	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
310	}
