312	SeekableReadBufferPtr ReadBufferS3Factory::getReader()
313	{
314	    const auto next_range = range_generator.nextRange();
315	    if (!next_range)
316	    {
317	        return nullptr;
318	    }
319	
320	    auto reader = std::make_shared<ReadBufferFromS3>(
321	        client_ptr,
322	        bucket,
323	        key,
324	        version_id,
325	        s3_max_single_read_retries,
326	        read_settings,
327	        false /*use_external_buffer*/,
328	        next_range->first,
329	        next_range->second);
330	    return reader;
331	}
