24	static std::optional<NamesAndTypesList> getOrderedColumnsList(
25	    const NamesAndTypesList & columns_list, const Names & columns_order_hint)
26	{
27	    if (columns_list.size() != columns_order_hint.size())
28	        return {};
29	
30	    std::unordered_map<String, DataTypePtr> available_columns;
31	    for (const auto & [name, type] : columns_list)
32	        available_columns.emplace(name, type);
33	
34	    NamesAndTypesList res;
35	    for (const auto & name : columns_order_hint)
36	    {
37	        auto it = available_columns.find(name);
38	        if (it == available_columns.end())
39	            return {};
40	
41	        res.emplace_back(name, it->second);
42	    }
43	    return res;
44	}
