46	bool isRetryableSchemaInferenceError(int code)
47	{
48	    return code == ErrorCodes::EMPTY_DATA_PASSED || code == ErrorCodes::ONLY_NULLS_WHILE_READING_SCHEMA;
49	}
50	
51	ColumnsDescription readSchemaFromFormat(
52	    const String & format_name,
53	    const std::optional<FormatSettings> & format_settings,
54	    ReadBufferIterator & read_buffer_iterator,
55	    bool retry,
56	    ContextPtr & context,
57	    std::unique_ptr<ReadBuffer> & buf)
58	{
59	    NamesAndTypesList names_and_types;
60	    if (FormatFactory::instance().checkIfFormatHasExternalSchemaReader(format_name))
61	    {
62	        auto external_schema_reader = FormatFactory::instance().getExternalSchemaReader(format_name, context, format_settings);
63	        try
64	        {
65	            names_and_types = external_schema_reader->readSchema();
66	        }
67	        catch (const DB::Exception & e)
68	        {
69	            throw Exception(ErrorCodes::CANNOT_EXTRACT_TABLE_STRUCTURE, "Cannot extract table structure from {} format file. Error: {}. You can specify the structure manually", format_name, e.message());
70	        }
71	    }
72	    else if (FormatFactory::instance().checkIfFormatHasSchemaReader(format_name))
73	    {
74	        std::string exception_messages;
75	        SchemaReaderPtr schema_reader;
76	        size_t max_rows_to_read = format_settings ? format_settings->max_rows_to_read_for_schema_inference : context->getSettingsRef().input_format_max_rows_to_read_for_schema_inference;
77	        size_t iterations = 0;
78	        while (true)
79	        {
80	            bool is_eof = false;
81	            try
82	            {
83	                buf = read_buffer_iterator();
84	                if (!buf)
85	                    break;
86	                is_eof = buf->eof();
87	            }
88	            catch (...)
89	            {
90	                auto exception_message = getCurrentExceptionMessage(false);
91	                throw Exception(ErrorCodes::CANNOT_EXTRACT_TABLE_STRUCTURE, "Cannot extract table structure from {} format file: {}. You can specify the structure manually", format_name, exception_message);
92	            }
93	            ++iterations;
94	
95	            if (is_eof)
96	            {
97	                auto exception_message = fmt::format("Cannot extract table structure from {} format file, file is empty", format_name);
98	
99	                if (!retry)
100	                    throw Exception(ErrorCodes::CANNOT_EXTRACT_TABLE_STRUCTURE, "{}. You can specify the structure manually", exception_message);
101	
102	                exception_messages += "\n" + exception_message;
103	                continue;
104	            }
105	
106	            try
107	            {
108	                schema_reader = FormatFactory::instance().getSchemaReader(format_name, *buf, context, format_settings);
109	                schema_reader->setMaxRowsToRead(max_rows_to_read);
110	                names_and_types = schema_reader->readSchema();
111	                break;
112	            }
113	            catch (...)
114	            {
115	                auto exception_message = getCurrentExceptionMessage(false);
116	                if (schema_reader)
117	                {
118	                    size_t rows_read = schema_reader->getNumRowsRead();
119	                    assert(rows_read <= max_rows_to_read);
120	                    max_rows_to_read -= schema_reader->getNumRowsRead();
121	                    if (rows_read != 0 && max_rows_to_read == 0)
122	                    {
123	                        exception_message += "\nTo increase the maximum number of rows to read for structure determination, use setting input_format_max_rows_to_read_for_schema_inference";
124	                        if (iterations > 1)
125	                        {
126	                            exception_messages += "\n" + exception_message;
127	                            break;
128	                        }
129	                        retry = false;
130	                    }
131	                }
132	
133	                if (!retry || !isRetryableSchemaInferenceError(getCurrentExceptionCode()))
134	                    throw Exception(ErrorCodes::CANNOT_EXTRACT_TABLE_STRUCTURE, "Cannot extract table structure from {} format file. Error: {}. You can specify the structure manually", format_name, exception_message);
135	
136	                exception_messages += "\n" + exception_message;
137	            }
138	        }
139	
140	        if (names_and_types.empty())
141	            throw Exception(ErrorCodes::CANNOT_EXTRACT_TABLE_STRUCTURE, "All attempts to extract table structure from files failed. Errors:{}\nYou can specify the structure manually", exception_messages);
142	
143	        /// If we have "INSERT SELECT" query then try to order
144	        /// columns as they are ordered in table schema for formats
145	        /// without strict column order (like JSON and TSKV).
146	        /// It will allow to execute simple data loading with query
147	        /// "INSERT INTO table SELECT * FROM ..."
148	        const auto & insertion_table = context->getInsertionTable();
149	        if (!schema_reader->hasStrictOrderOfColumns() && !insertion_table.empty())
150	        {
151	            auto storage = DatabaseCatalog::instance().getTable(insertion_table, context);
152	            auto metadata = storage->getInMemoryMetadataPtr();
153	            auto names_in_storage = metadata->getColumns().getNamesOfPhysical();
154	            auto ordered_list = getOrderedColumnsList(names_and_types, names_in_storage);
155	            if (ordered_list)
156	                names_and_types = *ordered_list;
157	        }
158	    }
159	    else
160	        throw Exception(ErrorCodes::BAD_ARGUMENTS, "{} file format doesn't support schema inference. You must specify the structure manually", format_name);
161	
162	    return ColumnsDescription(names_and_types);
163	}
