165	ColumnsDescription readSchemaFromFormat(const String & format_name, const std::optional<FormatSettings> & format_settings, ReadBufferIterator & read_buffer_iterator, bool retry, ContextPtr & context)
166	{
167	    std::unique_ptr<ReadBuffer> buf_out;
168	    return readSchemaFromFormat(format_name, format_settings, read_buffer_iterator, retry, context, buf_out);
169	}
