171	DataTypePtr makeNullableRecursivelyAndCheckForNothing(DataTypePtr type)
172	{
173	    if (!type)
174	        return nullptr;
175	
176	    WhichDataType which(type);
177	
178	    if (which.isNothing())
179	        return nullptr;
180	
181	    if (which.isNullable())
182	    {
183	        const auto * nullable_type = assert_cast<const DataTypeNullable *>(type.get());
184	        return makeNullableRecursivelyAndCheckForNothing(nullable_type->getNestedType());
185	    }
186	
187	    if (which.isArray())
188	    {
189	        const auto * array_type = assert_cast<const DataTypeArray *>(type.get());
190	        auto nested_type = makeNullableRecursivelyAndCheckForNothing(array_type->getNestedType());
191	        return nested_type ? std::make_shared<DataTypeArray>(nested_type) : nullptr;
192	    }
193	
194	    if (which.isTuple())
195	    {
196	        const auto * tuple_type = assert_cast<const DataTypeTuple *>(type.get());
197	        DataTypes nested_types;
198	        for (const auto & element : tuple_type->getElements())
199	        {
200	            auto nested_type = makeNullableRecursivelyAndCheckForNothing(element);
201	            if (!nested_type)
