211	        auto key_type = makeNullableRecursivelyAndCheckForNothing(map_type->getKeyType());
212	        auto value_type = makeNullableRecursivelyAndCheckForNothing(map_type->getValueType());
213	        return key_type && value_type ? std::make_shared<DataTypeMap>(removeNullable(key_type), value_type) : nullptr;
214	    }
215	
216	    if (which.isLowCarnality())
217	    {
218	        const auto * lc_type = assert_cast<const DataTypeLowCardinality *>(type.get());
219	        auto nested_type = makeNullableRecursivelyAndCheckForNothing(lc_type->getDictionaryType());
220	        return nested_type ? std::make_shared<DataTypeLowCardinality>(nested_type) : nullptr;
221	    }
222	
223	    return makeNullable(type);
