21	ConnectionEstablisher::ConnectionEstablisher(
22	    IConnectionPool * pool_,
23	    const ConnectionTimeouts * timeouts_,
24	    const Settings * settings_,
25	    Poco::Logger * log_,
26	    const QualifiedTableName * table_to_check_)
27	    : pool(pool_), timeouts(timeouts_), settings(settings_), log(log_), table_to_check(table_to_check_), is_finished(false)
28	{
