119	void ConnectionEstablisherAsync::Routine::ReadCallback::operator()(int fd, Poco::Timespan timeout, const std::string &)
120	{
121	    /// Check if it's the first time and we need to add socket fd to epoll.
122	    if (connection_establisher_async.socket_fd == -1)
123	    {
124	        connection_establisher_async.epoll.add(fd);
125	        connection_establisher_async.socket_fd = fd;
126	    }
127	
128	    connection_establisher_async.receive_timeout.setRelative(timeout);
129	    fiber = std::move(fiber).resume();
130	    connection_establisher_async.receive_timeout.reset();
131	}
132	
133	Fiber ConnectionEstablisherAsync::Routine::operator()(Fiber && sink)
134	{
135	    try
136	    {
137	        connection_establisher_async.connection_establisher.setAsyncCallback(ReadCallback{connection_establisher_async, sink});
138	        connection_establisher_async.connection_establisher.run(connection_establisher_async.result, connection_establisher_async.fail_message);
139	    }
140	    catch (const boost::context::detail::forced_unwind &)
141	    {
142	        /// This exception is thrown by fiber implementation in case if fiber is being deleted but hasn't exited
143	        /// It should not be caught or it will segfault.
144	        /// Other exceptions must be caught
145	        throw;
146	    }
147	    catch (...)
148	    {
149	        connection_establisher_async.exception = std::current_exception();
150	    }
151	
152	    return std::move(sink);
153	}
