155	std::variant<int, ConnectionEstablisher::TryResult> ConnectionEstablisherAsync::resume()
156	{
157	    if (!fiber_created)
158	    {
159	        reset();
160	        fiber = boost::context::fiber(std::allocator_arg_t(), fiber_stack, Routine{*this});
161	        fiber_created = true;
162	    } else if (!checkReceiveTimeout())
163	        return result;
164	
165	    fiber = std::move(fiber).resume();
166	
167	    if (exception)
168	        std::rethrow_exception(exception);
169	
170	    if (connection_establisher.isFinished())
171	    {
172	        destroyFiber();
173	        return result;
174	    }
175	
176	    return epoll.getFileDescriptor();
177	}
178	
179	bool ConnectionEstablisherAsync::checkReceiveTimeout()
180	{
181	    bool is_socket_ready = false;
182	    bool is_receive_timeout_alarmed = false;
183	
184	    epoll_event events[2];
185	    events[0].data.fd = events[1].data.fd = -1;
186	    size_t ready_count = epoll.getManyReady(2, events, false);
187	    for (size_t i = 0; i != ready_count; ++i)
188	    {
189	        if (events[i].data.fd == socket_fd)
190	            is_socket_ready = true;
191	        if (events[i].data.fd == receive_timeout.getDescriptor())
192	            is_receive_timeout_alarmed = true;
193	    }
194	
195	    if (is_receive_timeout_alarmed && !is_socket_ready)
196	    {
197	        destroyFiber();
198	        /// In not async case this exception would be thrown and caught in ConnectionEstablisher::run,
199	        /// but in async case we process timeout outside and cannot throw exception. So, we just save fail message.
200	        fail_message = fmt::format(
201	            "Timeout exceeded while reading from socket ({}, receive timeout {} ms)",
202	            result.entry->getDescription(),
203	            result.entry->getSocket()->getReceiveTimeout().totalMilliseconds());
204	        epoll.remove(socket_fd);
205	        resetResult();
206	        return false;
207	    }
208	
209	    return true;
210	}
