466	void S3ObjectStorage::copyObject( // NOLINT
467	    const StoredObject & object_from, const StoredObject & object_to, std::optional<ObjectAttributes> object_to_attributes)
468	{
469	    auto head = requestObjectHeadData(bucket, object_from.absolute_path).GetResult();
470	    static constexpr int64_t multipart_upload_threashold = 5UL * 1024 * 1024 * 1024;
471	
472	    if (head.GetContentLength() >= multipart_upload_threashold)
473	    {
474	        copyObjectMultipartImpl(
475	            bucket, object_from.absolute_path, bucket, object_to.absolute_path, head, object_to_attributes);
476	    }
477	    else
478	    {
479	        copyObjectImpl(
480	            bucket, object_from.absolute_path, bucket, object_to.absolute_path, head, object_to_attributes);
481	    }
482	}
