507	void S3ObjectStorage::shutdown()
508	{
509	    auto client_ptr = client.get();
510	    /// This call stops any next retry attempts for ongoing S3 requests.
511	    /// If S3 request is failed and the method below is executed S3 client immediately returns the last failed S3 request outcome.
512	    /// If S3 is healthy nothing wrong will be happened and S3 requests will be processed in a regular way without errors.
513	    /// This should significantly speed up shutdown process if S3 is unhealthy.
514	    const_cast<Aws::S3::S3Client &>(*client_ptr).DisableRequestProcessing();
515	}
