86	void StorageSystemFunctions::fillData(MutableColumns & res_columns, ContextPtr context, const SelectQueryInfo &) const
87	{
88	    const auto & functions_factory = FunctionFactory::instance();
89	    const auto & function_names = functions_factory.getAllRegisteredNames();
90	    for (const auto & function_name : function_names)
91	    {
92	        fillRow(res_columns, function_name, UInt64(0), "", FunctionOrigin::SYSTEM, functions_factory);
93	    }
94	
95	    const auto & aggregate_functions_factory = AggregateFunctionFactory::instance();
96	    const auto & aggregate_function_names = aggregate_functions_factory.getAllRegisteredNames();
97	    for (const auto & function_name : aggregate_function_names)
98	    {
99	        fillRow(res_columns, function_name, UInt64(1), "", FunctionOrigin::SYSTEM, aggregate_functions_factory);
100	    }
101	
102	    const auto & user_defined_sql_functions_factory = UserDefinedSQLFunctionFactory::instance();
103	    const auto & user_defined_sql_functions_names = user_defined_sql_functions_factory.getAllRegisteredNames();
104	    for (const auto & function_name : user_defined_sql_functions_names)
105	    {
106	        auto create_query = queryToString(user_defined_sql_functions_factory.get(function_name));
107	        fillRow(res_columns, function_name, UInt64(0), create_query, FunctionOrigin::SQL_USER_DEFINED, user_defined_sql_functions_factory);
108	    }
109	
110	    const auto & user_defined_executable_functions_factory = UserDefinedExecutableFunctionFactory::instance();
111	    const auto & user_defined_executable_functions_names = user_defined_executable_functions_factory.getRegisteredNames(context);
112	    for (const auto & function_name : user_defined_executable_functions_names)
113	    {
114	        fillRow(res_columns, function_name, UInt64(0), "", FunctionOrigin::EXECUTABLE_USER_DEFINED, user_defined_executable_functions_factory);
115	    }
