118	void StorageSystemFunctions::backupData(BackupEntriesCollector & backup_entries_collector, const String & data_path_in_backup, const std::optional<ASTs> & /* partitions */)
119	{
120	    const auto & user_defined_sql_functions_factory = UserDefinedSQLFunctionFactory::instance();
121	    const auto & user_defined_sql_functions_names = user_defined_sql_functions_factory.getAllRegisteredNames();
122	    fs::path data_path_in_backup_fs{data_path_in_backup};
123	    for (const auto & function_name : user_defined_sql_functions_names)
124	    {
125	        auto ast = user_defined_sql_functions_factory.tryGet(function_name);
126	        if (!ast)
127	            continue;
128	        backup_entries_collector.addBackupEntry(
129	            data_path_in_backup_fs / (escapeForFileName(function_name) + ".sql"),
130	            std::make_shared<BackupEntryFromMemory>(queryToString(ast)));
131	    }
132	}
