134	void StorageSystemFunctions::restoreDataFromBackup(RestorerFromBackup & restorer, const String & data_path_in_backup, const std::optional<ASTs> & /* partitions */)
135	{
136	    auto backup = restorer.getBackup();
137	    fs::path data_path_in_backup_fs{data_path_in_backup};
138	
139	    Strings filenames = backup->listFiles(data_path_in_backup);
140	    for (const auto & filename : filenames)
141	    {
142	        if (!filename.ends_with(".sql"))
143	        {
144	            throw Exception(ErrorCodes::CANNOT_RESTORE_TABLE, "Cannot restore table {}: File name {} doesn't have the extension .sql",
145	                            getStorageID().getFullTableName(), String{data_path_in_backup_fs / filename});
146	        }
147	    }
148	
149	    auto & user_defined_sql_functions_factory = UserDefinedSQLFunctionFactory::instance();
150	    const auto & restore_settings = restorer.getRestoreSettings();
151	    auto context = restorer.getContext();
152	
153	    for (const auto & filename : filenames)
154	    {
155	        String escaped_function_name = filename.substr(0, filename.length() - strlen(".sql"));
156	        String function_name = unescapeForFileName(escaped_function_name);
157	
158	        String filepath = data_path_in_backup_fs / filename;
159	        auto function_def_entry = backup->readFile(filepath);
160	        auto function_def_in = function_def_entry->getReadBuffer();
161	        String function_def;
162	        readStringUntilEOF(function_def, *function_def_in);
163	
164	        ParserCreateFunctionQuery parser;
165	        ASTPtr ast = parseQuery(
166	            parser,
167	            function_def.data(),
168	            function_def.data() + function_def.size(),
169	            "in file " + filepath + " from backup " + backup->getName(),
170	            0,
171	            context->getSettingsRef().max_parser_depth);
172	
173	        bool replace = (restore_settings.create_function == RestoreUDFCreationMode::kReplace);
174	        bool if_not_exists = (restore_settings.create_function == RestoreUDFCreationMode::kCreateIfNotExists);
175	        user_defined_sql_functions_factory.registerFunction(context, function_name, ast, replace, if_not_exists, true);
176	    }
177	}
