158	Pipe ReadFromMergeTree::readFromPool(
159	    RangesInDataParts parts_with_range,
160	    Names required_columns,
161	    size_t max_streams,
162	    size_t min_marks_for_concurrent_read,
163	    bool use_uncompressed_cache)
164	{
165	    Pipes pipes;
166	    size_t sum_marks = 0;
167	    size_t total_rows = 0;
168	
169	    for (const auto & part : parts_with_range)
170	    {
171	        sum_marks += part.getMarksCount();
172	        total_rows += part.getRowsCount();
173	    }
174	
175	    const auto & settings = context->getSettingsRef();
176	    const auto & client_info = context->getClientInfo();
177	    MergeTreeReadPool::BackoffSettings backoff_settings(settings);
178	
179	    auto pool = std::make_shared<MergeTreeReadPool>(
180	        max_streams,
181	        sum_marks,
182	        min_marks_for_concurrent_read,
183	        std::move(parts_with_range),
184	        data,
185	        storage_snapshot,
186	        prewhere_info,
187	        required_columns,
188	        backoff_settings,
189	        settings.preferred_block_size_bytes,
190	        false);
191	
192	    auto * logger = &Poco::Logger::get(data.getLogName() + " (SelectExecutor)");
193	    LOG_DEBUG(logger, "Reading approx. {} rows with {} streams", total_rows, max_streams);
194	
195	    for (size_t i = 0; i < max_streams; ++i)
196	    {
197	        std::optional<ParallelReadingExtension> extension;
198	        if (read_task_callback)
199	        {
200	            extension = ParallelReadingExtension
201	            {
202	                .callback = read_task_callback.value(),
203	                .count_participating_replicas = client_info.count_participating_replicas,
204	                .number_of_current_replica = client_info.number_of_current_replica,
205	                .colums_to_read = required_columns
206	            };
207	        }
208	
209	        auto source = std::make_shared<MergeTreeThreadSelectProcessor>(
210	            i, pool, min_marks_for_concurrent_read, max_block_size,
211	            settings.preferred_block_size_bytes, settings.preferred_max_column_in_block_size_bytes,
212	            data, storage_snapshot, use_uncompressed_cache,
213	            prewhere_info, actions_settings, reader_settings, virt_column_names, std::move(extension));
214	
215	        /// Set the approximate number of rows for the first source only
216	        /// In case of parallel processing on replicas do not set approximate rows at all.
217	        /// Because the value will be identical on every replicas and will be accounted
218	        /// multiple times (settings.max_parallel_replicas times more)
219	        if (i == 0 && !client_info.collaborate_with_initiator)
220	            source->addTotalRowsApprox(total_rows);
221	
222	        pipes.emplace_back(std::move(source));
223	    }
224	
225	    return Pipe::unitePipes(std::move(pipes));
226	}
