1212	                /// so it looks safe enough to remove directory if we don't have uuid mapping for it.
1213	                /// No table or database using this directory should concurrently appear,
1214	                /// because creation of new table would fail with "directory already exists".
1215	                affected_dirs += maybeRemoveDirectory(uuid_dir.path());
1216	            }
1217	        }
1218	    }
1219	
1220	    if (affected_dirs)
1221	        LOG_INFO(log, "Cleaned up {} directories from store/", affected_dirs);
1222	
1223	    (*cleanup_task)->scheduleAfter(unused_dir_cleanup_period_sec * 1000);
