1226	bool DatabaseCatalog::maybeRemoveDirectory(const fs::path & unused_dir)
1227	{
1228	    /// "Safe" automatic removal of some directory.
1229	    /// At first we do not remove anything and only revoke all access right.
1230	    /// And remove only if nobody noticed it after, for example, one month.
1231	
1232	    struct stat st;
1233	    if (stat(unused_dir.string().c_str(), &st))
1234	    {
1235	        LOG_ERROR(log, "Failed to stat {}, errno: {}", unused_dir.string(), errno);
1236	        return false;
1237	    }
1238	
1239	    if (st.st_uid != geteuid())
1240	    {
1241	        /// Directory is not owned by clickhouse, it's weird, let's ignore it (chmod will likely fail anyway).
1242	        LOG_WARNING(log, "Found directory {} with unexpected owner (uid={})", unused_dir.string(), st.st_uid);
1243	        return false;
1244	    }
1245	
1246	    time_t max_modification_time = std::max(st.st_atime, std::max(st.st_mtime, st.st_ctime));
1247	    time_t current_time = time(nullptr);
1248	    if (st.st_mode & (S_IRWXU | S_IRWXG | S_IRWXO))
1249	    {
1250	        if (current_time <= max_modification_time + unused_dir_hide_timeout_sec)
1251	            return false;
1252	
1253	        LOG_INFO(log, "Removing access rights for unused directory {} (will remove it when timeout exceed)", unused_dir.string());
1254	
1255	        /// Explicitly update modification time just in case
1256	
1257	        struct utimbuf tb;
1258	        tb.actime = current_time;
1259	        tb.modtime = current_time;
1260	        if (utime(unused_dir.string().c_str(), &tb) != 0)
1261	            LOG_ERROR(log, "Failed to utime {}, errno: {}", unused_dir.string(), errno);
1262	
1263	        /// Remove all access right
1264	        if (chmod(unused_dir.string().c_str(), 0))
1265	            LOG_ERROR(log, "Failed to chmod {}, errno: {}", unused_dir.string(), errno);
1266	
1267	        return true;
1268	    }
1269	    else
1270	    {
1271	        if (!unused_dir_rm_timeout_sec)
1272	            return false;
1273	
1274	        if (current_time <= max_modification_time + unused_dir_rm_timeout_sec)
1275	            return false;
1276	
1277	        LOG_INFO(log, "Removing unused directory {}", unused_dir.string());
1278	
1279	        /// We have to set these access rights to make recursive removal work
1280	        if (chmod(unused_dir.string().c_str(), S_IRWXU))
1281	            LOG_ERROR(log, "Failed to chmod {}, errno: {}", unused_dir.string(), errno);
1282	
1283	        fs::remove_all(unused_dir);
1284	
1285	        return true;
1286	    }
1287	}
