508	    {
509	        if (which < rhs.which)
510	            return true;
511	        if (which > rhs.which)
512	            return false;
513	
514	        switch (which)
515	        {
516	            case Types::Null:    return true;
517	            case Types::Bool: [[fallthrough]];
518	            case Types::UInt64:  return get<UInt64>()  <= rhs.get<UInt64>();
519	            case Types::UInt128: return get<UInt128>() <= rhs.get<UInt128>();
