524	            case Types::UUID:    return get<UUID>().toUnderType() <= rhs.get<UUID>().toUnderType();
525	            case Types::Float64: return get<Float64>() <= rhs.get<Float64>();
526	            case Types::String:  return get<String>()  <= rhs.get<String>();
527	            case Types::Array:   return get<Array>()   <= rhs.get<Array>();
528	            case Types::Tuple:   return get<Tuple>()   <= rhs.get<Tuple>();
