637	    std::aligned_union_t<DBMS_MIN_FIELD_SIZE - sizeof(Types::Which),
638	        Null, UInt64, UInt128, UInt256, Int64, Int128, Int256, UUID, Float64, String, Array, Tuple, Map,
639	        DecimalField<Decimal32>, DecimalField<Decimal64>, DecimalField<Decimal128>, DecimalField<Decimal256>,
640	        AggregateFunctionStateData
641	        > storage;
