174	Block SharedLibraryHandler::dataToBlock(const ClickHouseLibrary::RawClickHouseLibraryTable data)
175	{
176	    if (!data)
177	        throw Exception("LibraryDictionarySource: No data returned", ErrorCodes::EXTERNAL_LIBRARY_ERROR);
178	
179	    const auto * columns_received = static_cast<const ClickHouseLibrary::Table *>(data);
180	    if (columns_received->error_code)
181	        throw Exception(
182	            "LibraryDictionarySource: Returned error: " + std::to_string(columns_received->error_code) + " " + (columns_received->error_string ? columns_received->error_string : ""),
183	            ErrorCodes::EXTERNAL_LIBRARY_ERROR);
184	
185	    MutableColumns columns = sample_block.cloneEmptyColumns();
186	
187	    for (size_t col_n = 0; col_n < columns_received->size; ++col_n)
188	    {
189	        if (columns.size() != columns_received->data[col_n].size)
190	            throw Exception(
191	                "LibraryDictionarySource: Returned unexpected number of columns: " + std::to_string(columns_received->data[col_n].size) + ", must be " + std::to_string(columns.size()),
192	                ErrorCodes::SIZES_OF_COLUMNS_DOESNT_MATCH);
193	
194	        for (size_t row_n = 0; row_n < columns_received->data[col_n].size; ++row_n)
195	        {
196	            const auto & field = columns_received->data[col_n].data[row_n];
197	            if (!field.data)
198	            {
199	                /// sample_block contains null_value (from config) inside corresponding column
200	                const auto & col = sample_block.getByPosition(row_n);
201	                columns[row_n]->insertFrom(*(col.column), 0);
202	            }
203	            else
204	            {
205	                const auto & size = field.size;
206	                columns[row_n]->insertData(static_cast<const char *>(field.data), size);
207	            }
208	        }
209	    }
210	
211	    return sample_block.cloneWithColumns(std::move(columns));
212	}
213	
214	}

