235	{
236	    auto zookeeper = storage.getZooKeeper();
237	
238	    Strings failed_parts;
239	    if (zookeeper->tryGetChildren(storage.zookeeper_path + "/quorum/failed_parts", failed_parts) != Coordination::Error::ZOK)
240	        return;
241	
242	    /// Firstly, remove parts from ZooKeeper
