261	{
262	    auto zookeeper = storage.getZooKeeper();
263	
264	    String quorum_str;
265	    if (zookeeper->tryGet(fs::path(storage.zookeeper_path) / "quorum" / "status", quorum_str))
266	    {
267	        ReplicatedMergeTreeQuorumEntry quorum_entry(quorum_str);
268	
269	        if (!quorum_entry.replicas.contains(storage.replica_name)
270	            && storage.getActiveContainingPart(quorum_entry.part_name))
271	        {
