275	    }
276	
277	    Strings part_names;
278	    String parallel_quorum_parts_path = fs::path(storage.zookeeper_path) / "quorum" / "parallel";
279	    if (zookeeper->tryGetChildren(parallel_quorum_parts_path, part_names) == Coordination::Error::ZOK)
280	    {
281	        for (auto & part_name : part_names)
282	        {
