299	{
300	    auto zookeeper = storage.getZooKeeper();
301	
302	    /// How other replicas can access this one.
303	    ReplicatedMergeTreeAddress address = storage.getReplicatedMergeTreeAddress();
304	
305	    String is_active_path = fs::path(storage.replica_path) / "is_active";
306	    zookeeper->waitForEphemeralToDisappearIfAny(is_active_path);
307	
308	    /// Simultaneously declare that this replica is active, and update the host.
309	    Coordination::Requests ops;
310	    ops.emplace_back(zkutil::makeCreateRequest(is_active_path, active_node_identifier, zkutil::CreateMode::Ephemeral));
311	    ops.emplace_back(zkutil::makeSetRequest(fs::path(storage.replica_path) / "host", address.toString(), -1));
312	
313	    try
314	    {
315	        zookeeper->multi(ops);
316	    }
317	    catch (const Coordination::Exception & e)
318	    {
319	        String existing_replica_host;
320	        zookeeper->tryGet(fs::path(storage.replica_path) / "host", existing_replica_host);
321	
322	        if (existing_replica_host.empty())
323	            existing_replica_host = "without host node";
324	        else
325	            boost::replace_all(existing_replica_host, "\n", ", ");
326	
327	        if (e.code == Coordination::Error::ZNODEEXISTS)
328	            throw Exception(ErrorCodes::REPLICA_IS_ALREADY_ACTIVE,
329	                "Replica {} appears to be already active ({}). If you're sure it's not, "
330	                "try again in a minute or remove znode {}/is_active manually",
331	                storage.replica_path, existing_replica_host, storage.replica_path);
332	
333	        throw;
334	    }
335	
336	    /// `current_zookeeper` lives for the lifetime of `replica_is_active_node`,
337	    ///  since before changing `current_zookeeper`, `replica_is_active_node` object is destroyed in `partialShutdown` method.
338	    storage.replica_is_active_node = zkutil::EphemeralNodeHolder::existing(is_active_path, *storage.current_zookeeper);
