342	void ReplicatedMergeTreeRestartingThread::partialShutdown(bool part_of_full_shutdown)
343	{
344	    setReadonly(part_of_full_shutdown);
345	    ProfileEvents::increment(ProfileEvents::ReplicaPartialShutdown);
346	
347	    storage.partial_shutdown_called = true;
348	    storage.partial_shutdown_event.set();
349	    storage.replica_is_active_node = nullptr;
350	
351	    LOG_TRACE(log, "Waiting for threads to finish");
352	
353	    storage.merge_selecting_task->deactivate();
354	    storage.queue_updating_task->deactivate();
355	    storage.mutations_updating_task->deactivate();
356	    storage.mutations_finalizing_task->deactivate();
357	
358	    storage.cleanup_thread.stop();
359	
360	    /// Stop queue processing
361	    {
362	        auto fetch_lock = storage.fetcher.blocker.cancel();
363	        auto merge_lock = storage.merger_mutator.merges_blocker.cancel();
364	        auto move_lock = storage.parts_mover.moves_blocker.cancel();
365	        storage.background_operations_assignee.finish();
366	    }
367	
368	    /// Stop part_check_thread after queue processing, because some queue tasks may restart part_check_thread
369	    storage.part_check_thread.stop();
370	
371	    LOG_TRACE(log, "Threads finished");
372	}
