100	void ASTIdentifier::formatImplWithoutAlias(const FormatSettings & settings, FormatState & state, FormatStateStacked frame) const
101	{
102	    auto format_element = [&](const String & elem_name)
103	    {
104	        settings.ostr << (settings.hilite ? hilite_identifier : "");
105	        settings.writeIdentifier(elem_name);
106	        settings.ostr << (settings.hilite ? hilite_none : "");
107	    };
108	
109	    if (compound())
110	    {
111	        for (size_t i = 0, j = 0, size = name_parts.size(); i < size; ++i)
112	        {
113	            if (i != 0)
114	                settings.ostr << '.';
115	
116	            /// Some AST rewriting code, like IdentifierSemantic::setColumnLongName,
117	            /// does not respect children of identifier.
118	            /// Here we also ignore children if they are empty.
119	            if (name_parts[i].empty() && j < children.size())
120	            {
121	                children[j]->formatImpl(settings, state, frame);
122	                ++j;
123	            }
124	            else
125	                format_element(name_parts[i]);
126	        }
127	    }
128	    else
129	    {
130	        const auto & name = shortName();
131	        if (name.empty() && !children.empty())
132	            children.front()->formatImpl(settings, state, frame);
133	        else
134	            format_element(name);
135	    }
136	}
