22	void dumpToMapColumn(const Counters::Snapshot & counters, DB::IColumn * column, bool nonzero_only)
23	{
24	    auto * column_map = column ? &typeid_cast<DB::ColumnMap &>(*column) : nullptr;
25	    if (!column_map)
26	        return;
27	
28	    auto & offsets = column_map->getNestedColumn().getOffsets();
29	    auto & tuple_column = column_map->getNestedData();
30	    auto & key_column = tuple_column.getColumn(0);
31	    auto & value_column = tuple_column.getColumn(1);
32	
33	    size_t size = 0;
34	    for (Event event = 0; event < Counters::num_counters; ++event)
35	    {
36	        UInt64 value = counters[event];
37	
38	        if (nonzero_only && 0 == value)
39	            continue;
40	
41	        const char * desc = getName(event);
42	        key_column.insertData(desc, strlen(desc));
43	        value_column.insert(value);
44	        size++;
45	    }
46	
47	    offsets.push_back(offsets.back() + size);
48	}
