51	static void dumpProfileEvents(ProfileEventsSnapshot const & snapshot, DB::MutableColumns & columns, String const & host_name)
52	{
53	    size_t rows = 0;
54	    auto & name_column = columns[NAME_COLUMN_INDEX];
55	    auto & value_column = columns[VALUE_COLUMN_INDEX];
56	    for (Event event = 0; event < Counters::num_counters; ++event)
57	    {
58	        Int64 value = snapshot.counters[event];
59	
60	        if (value == 0)
61	            continue;
62	
63	        const char * desc = getName(event);
64	        name_column->insertData(desc, strlen(desc));
65	        value_column->insert(value);
66	        rows++;
67	    }
68	
69	    // Fill the rest of the columns with data
70	    for (size_t row = 0; row < rows; ++row)
71	    {
72	        size_t i = 0;
73	        columns[i++]->insertData(host_name.data(), host_name.size());
74	        columns[i++]->insert(static_cast<UInt64>(snapshot.current_time));
75	        columns[i++]->insert(UInt64{snapshot.thread_id});
76	        columns[i++]->insert(Type::INCREMENT);
77	    }
78	}
