504	    String parsePattern(const String & pattern, std::vector<Action<T>> & instructions) const
505	    {
506	        String result;
507	
508	        const char * pos = pattern.data();
509	        const char * end = pos + pattern.size();
510	
511	        /// Add shift to previous action; or if there were none, add noop action with shift.
512	        auto add_shift = [&](size_t amount)
513	        {
514	            if (instructions.empty())
515	                instructions.emplace_back(&Action<T>::noop);
516	            instructions.back().shift += amount;
517	        };
518	
519	        /// If the argument was DateTime, add instruction for printing. If it was date, just shift (the buffer is pre-filled with default values).
520	        auto add_instruction_or_shift = [&](typename Action<T>::Func func [[maybe_unused]], size_t shift)
521	        {
522	            if constexpr (std::is_same_v<T, UInt32>)
523	                instructions.emplace_back(func, shift);
524	            else if constexpr (std::is_same_v<T, Int64>)
525	                instructions.emplace_back(func, shift);
526	            else
527	                add_shift(shift);
528	        };
529	
530	        while (true)
531	        {
532	            const char * percent_pos = find_first_symbols<'%'>(pos, end);
533	
534	            if (percent_pos < end)
535	            {
536	                if (pos < percent_pos)
537	                {
538	                    result.append(pos, percent_pos);
539	                    add_shift(percent_pos - pos);
540	                }
541	
542	                pos = percent_pos + 1;
543	
544	                if (pos >= end)
545	                    throw Exception("Sign '%' is the last in pattern, if you need it, use '%%'", ErrorCodes::BAD_ARGUMENTS);
546	
547	                switch (*pos)
548	                {
549	                    // Year, divided by 100, zero-padded
550	                    case 'C':
551	                        instructions.emplace_back(&Action<T>::century, 2);
552	                        result.append("00");
