305	
306	    if (!(status == Poco::Net::HTTPResponse::HTTP_OK
307	        || status == Poco::Net::HTTPResponse::HTTP_CREATED
308	        || status == Poco::Net::HTTPResponse::HTTP_ACCEPTED
309	        || status == Poco::Net::HTTPResponse::HTTP_PARTIAL_CONTENT /// Reading with Range header was successful.
