21	void OwnSplitChannel::log(const Poco::Message & msg)
22	{
23	
24	#ifdef WITH_TEXT_LOG
25	    auto logs_queue = CurrentThread::getInternalTextLogsQueue();
26	
27	    if (channels.empty() && (logs_queue == nullptr || !logs_queue->isNeeded(msg.getPriority(), msg.getSource())))
28	        return;
29	#endif
30	
31	    if (auto * masker = SensitiveDataMasker::getInstance())
32	    {
33	        auto message_text = msg.getText();
34	        auto matches = masker->wipeSensitiveData(message_text);
35	        if (matches > 0)
36	        {
37	            tryLogSplit({msg, message_text}); // we will continue with the copy of original message with text modified
38	            return;
39	        }
40	
41	    }
42	
43	    tryLogSplit(msg);
44	}
