79	void OwnSplitChannel::logSplit(const Poco::Message & msg)
80	{
81	    ExtendedLogMessage msg_ext = ExtendedLogMessage::getFrom(msg);
82	
83	    /// Log data to child channels
84	    for (auto & [name, channel] : channels)
85	    {
86	        if (channel.second)
87	            channel.second->logExtended(msg_ext); // extended child
88	        else
89	            channel.first->log(msg); // ordinary child
90	    }
91	
92	#ifdef WITH_TEXT_LOG
93	    auto logs_queue = CurrentThread::getInternalTextLogsQueue();
94	
95	    /// Log to "TCP queue" if message is not too noisy
96	    if (logs_queue && logs_queue->isNeeded(msg.getPriority(), msg.getSource()))
97	    {
98	        MutableColumns columns = InternalTextLogsQueue::getSampleColumns();
99	
100	        size_t i = 0;
101	        columns[i++]->insert(msg_ext.time_seconds);
102	        columns[i++]->insert(msg_ext.time_microseconds);
103	        columns[i++]->insert(DNSResolver::instance().getHostName());
104	        columns[i++]->insert(msg_ext.query_id);
105	        columns[i++]->insert(msg_ext.thread_id);
106	        columns[i++]->insert(static_cast<Int64>(msg.getPriority()));
107	        columns[i++]->insert(msg.getSource());
108	        columns[i++]->insert(msg.getText());
109	
110	        [[maybe_unused]] bool push_result = logs_queue->emplace(std::move(columns));
111	    }
112	
113	    /// Also log to system.text_log table, if message is not too noisy
114	    auto text_log_max_priority_loaded = text_log_max_priority.load(std::memory_order_relaxed);
115	    if (text_log_max_priority_loaded && msg.getPriority() <= text_log_max_priority_loaded)
116	    {
117	        TextLogElement elem;
118	
119	        elem.event_time = msg_ext.time_seconds;
120	        elem.event_time_microseconds = msg_ext.time_in_microseconds;
121	        elem.microseconds = msg_ext.time_microseconds;
122	
123	        elem.thread_name = getThreadName();
124	        elem.thread_id = msg_ext.thread_id;
125	
126	        elem.query_id = msg_ext.query_id;
127	
128	        elem.message = msg.getText();
129	        elem.logger_name = msg.getSource();
130	        elem.level = msg.getPriority();
131	
132	        if (msg.getSourceFile() != nullptr)
133	            elem.source_file = msg.getSourceFile();
134	
135	        elem.source_line = msg.getSourceLine();
136	        std::shared_ptr<TextLog> text_log_locked{};
137	        {
138	            std::lock_guard<std::mutex> lock(text_log_mutex);
139	            text_log_locked = text_log.lock();
140	        }
141	        if (text_log_locked)
142	            text_log_locked->add(elem);
143	    }
144	#endif
145	}
