51	off_t ReadIndirectBufferFromRemoteFS::seek(off_t offset_, int whence)
52	{
53	    if (whence == SEEK_CUR)
54	    {
55	        /// If position within current working buffer - shift pos.
56	        if (!working_buffer.empty() && size_t(getPosition() + offset_) < impl->file_offset_of_buffer_end)
57	        {
58	            pos += offset_;
59	            return getPosition();
60	        }
61	        else
62	        {
63	            impl->file_offset_of_buffer_end += offset_;
64	        }
65	    }
66	    else if (whence == SEEK_SET)
67	    {
68	        /// If position within current working buffer - shift pos.
69	        if (!working_buffer.empty()
70	            && size_t(offset_) >= impl->file_offset_of_buffer_end - working_buffer.size()
71	            && size_t(offset_) < impl->file_offset_of_buffer_end)
72	        {
73	            pos = working_buffer.end() - (impl->file_offset_of_buffer_end - offset_);
74	            return getPosition();
75	        }
76	        else
77	        {
78	            impl->file_offset_of_buffer_end = offset_;
79	        }
80	    }
81	    else
82	        throw Exception("Only SEEK_SET or SEEK_CUR modes are allowed.", ErrorCodes::CANNOT_SEEK_THROUGH_FILE);
83	
84	    impl->reset();
85	    resetWorkingBuffer();
86	
87	    file_offset_of_buffer_end = impl->file_offset_of_buffer_end;
88	    return impl->file_offset_of_buffer_end;
89	}
90	
91	
92	bool ReadIndirectBufferFromRemoteFS::nextImpl()
93	{
94	    /// Transfer current position and working_buffer to actual ReadBuffer
95	    swap(*impl);
96	
97	    assert(!impl->hasPendingData());
98	    /// Position and working_buffer will be updated in next() call
99	    auto result = impl->next();
100	    /// and assigned to current buffer.
101	    swap(*impl);
102	
103	    if (result)
104	    {
105	        file_offset_of_buffer_end += available();
106	        BufferBase::set(working_buffer.begin() + offset(), available(), 0);
107	    }
108	
109	    assert(file_offset_of_buffer_end == impl->file_offset_of_buffer_end);
110	
111	    return result;
112	}
