591	class FunctionDateOrDateTimeAddInterval : public IFunction
592	{
593	public:
594	    static constexpr auto name = Transform::name;
595	    static FunctionPtr create(ContextPtr) { return std::make_shared<FunctionDateOrDateTimeAddInterval>(); }
596	
597	    String getName() const override
598	    {
599	        return name;
600	    }
601	
602	    bool isVariadic() const override { return true; }
603	    size_t getNumberOfArguments() const override { return 0; }
604	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return false; }
605	
606	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
607	    {
608	        if (arguments.size() != 2 && arguments.size() != 3)
609	            throw Exception("Number of arguments for function " + getName() + " doesn't match: passed "
610	                + toString(arguments.size()) + ", should be 2 or 3",
611	                ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
612	
613	        if (!isNativeNumber(arguments[1].type))
614	            throw Exception("Second argument for function " + getName() + " (delta) must be number",
615	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
616	
617	        if (arguments.size() == 2)
618	        {
619	            if (!isDate(arguments[0].type) && !isDate32(arguments[0].type) && !isDateTime(arguments[0].type) && !isDateTime64(arguments[0].type))
620	                throw Exception{"Illegal type " + arguments[0].type->getName() + " of first argument of function " + getName() +
621	                    ". Should be a date or a date with time", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT};
622	        }
623	        else
624	        {
625	            if (!WhichDataType(arguments[0].type).isDateTime()
626	                || !WhichDataType(arguments[2].type).isString())
627	            {
628	                throw Exception(
629	                    "Function " + getName() + " supports 2 or 3 arguments. The 1st argument "
630	                    "must be of type Date or DateTime. The 2nd argument must be number. "
631	                    "The 3rd argument (optional) must be "
632	                    "a constant string with timezone name. The timezone argument is allowed "
633	                    "only when the 1st argument has the type DateTime",
634	                    ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
635	            }
636	        }
637	
638	        switch (arguments[0].type->getTypeId())
639	        {
640	            case TypeIndex::Date:
641	                return resolveReturnType<DataTypeDate>(arguments);
642	            case TypeIndex::Date32:
643	                return resolveReturnType<DataTypeDate32>(arguments);
644	            case TypeIndex::DateTime:
645	                return resolveReturnType<DataTypeDateTime>(arguments);
646	            case TypeIndex::DateTime64:
647	                return resolveReturnType<DataTypeDateTime64>(arguments);
648	            default:
649	            {
650	                throw Exception("Invalid type of 1st argument of function " + getName() + ": "
651	                    + arguments[0].type->getName() + ", expected: Date, DateTime or DateTime64.",
652	                    ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
653	            }
654	        }
655	    }
656	
657	    /// Helper templates to deduce return type based on argument type, since some overloads may promote or denote types,
658	    /// e.g. addSeconds(Date, 1) => DateTime
659	    template <typename FieldType>
660	    using TransformExecuteReturnType = decltype(std::declval<Transform>().execute(FieldType(), 0, std::declval<DateLUTImpl>(), 0));
661	
662	    // Deduces RETURN DataType from INPUT DataType, based on return type of Transform{}.execute(INPUT_TYPE, UInt64, DateLUTImpl).
663	    // e.g. for Transform-type that has execute()-overload with 'UInt16' input and 'UInt32' return,
664	    // argument type is expected to be 'Date', and result type is deduced to be 'DateTime'.
665	    template <typename FromDataType>
666	    using TransformResultDataType = typename date_and_time_type_details::ResultDataTypeMap<TransformExecuteReturnType<typename FromDataType::FieldType>>::ResultDataType;
667	
668	    template <typename FromDataType>
669	    DataTypePtr resolveReturnType(const ColumnsWithTypeAndName & arguments) const
670	    {
671	        using ResultDataType = TransformResultDataType<FromDataType>;
672	
673	        if constexpr (std::is_same_v<ResultDataType, DataTypeDate>)
674	            return std::make_shared<DataTypeDate>();
675	        else if constexpr (std::is_same_v<ResultDataType, DataTypeDate32>)
676	            return std::make_shared<DataTypeDate32>();
677	        else if constexpr (std::is_same_v<ResultDataType, DataTypeDateTime>)
678	        {
679	            return std::make_shared<DataTypeDateTime>(extractTimeZoneNameFromFunctionArguments(arguments, 2, 0));
680	        }
681	        else if constexpr (std::is_same_v<ResultDataType, DataTypeDateTime64>)
682	        {
683	            if (typeid_cast<const DataTypeDateTime64 *>(arguments[0].type.get()))
684	            {
685	                const auto & datetime64_type = assert_cast<const DataTypeDateTime64 &>(*arguments[0].type);
686	
687	                auto from_scale = datetime64_type.getScale();
688	                auto scale = from_scale;
689	
690	                if (std::is_same_v<Transform, AddNanosecondsImpl>)
691	                    scale = 9;
692	                else if (std::is_same_v<Transform, AddMicrosecondsImpl>)
693	                    scale = 6;
694	                else if (std::is_same_v<Transform, AddMillisecondsImpl>)
695	                    scale = 3;
696	
697	                scale = std::max(scale, from_scale);
698	
699	                return std::make_shared<DataTypeDateTime64>(scale, extractTimeZoneNameFromFunctionArguments(arguments, 2, 0));
700	            }
701	            else
702	            {
703	                auto scale = DataTypeDateTime64::default_scale;
704	
705	                if (std::is_same_v<Transform, AddNanosecondsImpl>)
706	                    scale = 9;
707	                else if (std::is_same_v<Transform, AddMicrosecondsImpl>)
708	                    scale = 6;
709	                else if (std::is_same_v<Transform, AddMillisecondsImpl>)
710	                    scale = 3;
711	
712	                return std::make_shared<DataTypeDateTime64>(scale, extractTimeZoneNameFromFunctionArguments(arguments, 2, 0));
713	            }
714	        }
715	        else
716	        {
717	            static_assert("Failed to resolve return type.");
718	        }
719	
720	        //to make PVS and GCC happy.
721	        return nullptr;
722	    }
