725	    ColumnNumbers getArgumentsThatAreAlwaysConstant() const override { return {2}; }
726	
727	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t /*input_rows_count*/) const override
728	    {
729	        const IDataType * from_type = arguments[0].type.get();
730	        WhichDataType which(from_type);
731	
732	        if (which.isDate())
733	        {
734	            return DateTimeAddIntervalImpl<DataTypeDate, TransformResultDataType<DataTypeDate>, Transform>::execute(
735	                Transform{}, arguments, result_type);
736	        }
737	        else if (which.isDate32())
738	        {
739	            return DateTimeAddIntervalImpl<DataTypeDate32, TransformResultDataType<DataTypeDate32>, Transform>::execute(
740	                Transform{}, arguments, result_type);
741	        }
742	        else if (which.isDateTime())
743	        {
744	            return DateTimeAddIntervalImpl<DataTypeDateTime, TransformResultDataType<DataTypeDateTime>, Transform>::execute(
745	                Transform{}, arguments, result_type);
746	        }
747	        else if (const auto * datetime64_type = assert_cast<const DataTypeDateTime64 *>(from_type))
748	        {
749	            auto from_scale = datetime64_type->getScale();
750	            return DateTimeAddIntervalImpl<DataTypeDateTime64, TransformResultDataType<DataTypeDateTime64>, Transform>::execute(
751	                Transform{}, arguments, result_type, from_scale);
752	        }
753	        else
754	            throw Exception("Illegal type " + arguments[0].type->getName() + " of first argument of function " + getName(),
755	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
756	    }
757	};
