15	class ParserLiteralOrMap : public IParserBase
16	{
17	public:
18	protected:
19	    const char * getName() const override { return "literal or map"; }
20	    bool parseImpl(Pos & pos, ASTPtr & node, Expected & expected) override
21	    {
22	        {
23	            ParserLiteral literal;
24	            if (literal.parse(pos, node, expected))
25	                return true;
26	        }
27	
28	        ParserToken l_br(TokenType::OpeningCurlyBrace);
29	        ParserToken r_br(TokenType::ClosingCurlyBrace);
30	        ParserToken comma(TokenType::Comma);
31	        ParserToken colon(TokenType::Colon);
32	        ParserStringLiteral literal;
33	
34	        if (!l_br.ignore(pos, expected))
35	            return false;
36	
37	        Map map;
38	
39	        while (!r_br.ignore(pos, expected))
40	        {
41	            if (!map.empty() && !comma.ignore(pos, expected))
42	                return false;
43	
44	            ASTPtr key;
45	            ASTPtr val;
46	
47	            if (!literal.parse(pos, key, expected))
48	                return false;
49	
50	            if (!colon.ignore(pos, expected))
51	                return false;
52	
53	            if (!literal.parse(pos, val, expected))
54	                return false;
55	
56	            Tuple tuple;
57	            tuple.push_back(std::move(key->as<ASTLiteral>()->value));
58	            tuple.push_back(std::move(val->as<ASTLiteral>()->value));
59	            map.push_back(std::move(tuple));
60	        }
61	
62	        node = std::make_shared<ASTLiteral>(std::move(map));
63	        return true;
64	    }
65	};
