67	/// Parse `name = value`.
68	bool ParserSetQuery::parseNameValuePair(SettingChange & change, IParser::Pos & pos, Expected & expected)
69	{
70	    ParserCompoundIdentifier name_p;
71	    ParserLiteralOrMap value_p;
72	    ParserToken s_eq(TokenType::Equals);
73	
74	    ASTPtr name;
75	    ASTPtr value;
76	
77	    if (!name_p.parse(pos, name, expected))
78	        return false;
79	
80	    if (!s_eq.ignore(pos, expected))
81	        return false;
82	
83	    if (ParserKeyword("TRUE").ignore(pos, expected))
84	        value = std::make_shared<ASTLiteral>(Field(static_cast<UInt64>(1)));
85	    else if (ParserKeyword("FALSE").ignore(pos, expected))
86	        value = std::make_shared<ASTLiteral>(Field(static_cast<UInt64>(0)));
87	    else if (!value_p.parse(pos, value, expected))
88	        return false;
89	
90	    tryGetIdentifierNameInto(name, change.name);
91	    change.value = value->as<ASTLiteral &>().value;
92	
93	    return true;
94	}
