97	bool ParserSetQuery::parseImpl(Pos & pos, ASTPtr & node, Expected & expected)
98	{
99	    ParserToken s_comma(TokenType::Comma);
100	
101	    if (!parse_only_internals)
102	    {
103	        ParserKeyword s_set("SET");
104	
105	        if (!s_set.ignore(pos, expected))
106	            return false;
107	
108	        /// Parse SET TRANSACTION ... queries using ParserTransactionControl
109	        if (ParserKeyword{"TRANSACTION"}.check(pos, expected))
110	            return false;
111	    }
112	
113	    SettingsChanges changes;
114	
115	    while (true)
116	    {
117	        if (!changes.empty() && !s_comma.ignore(pos))
118	            break;
119	
120	        changes.push_back(SettingChange{});
121	
122	        if (!parseNameValuePair(changes.back(), pos, expected))
123	            return false;
124	    }
125	
126	    auto query = std::make_shared<ASTSetQuery>();
127	    node = query;
128	
129	    query->is_standalone = !parse_only_internals;
130	    query->changes = std::move(changes);
131	
132	    return true;
133	}
