764	bool ParserGroupingSetsExpressionListElements::parseImpl(Pos & pos, ASTPtr & node, Expected & expected)
765	{
766	    auto command_list = std::make_shared<ASTExpressionList>();
767	    node = command_list;
768	
769	    ParserToken s_comma(TokenType::Comma);
770	    ParserToken s_open(TokenType::OpeningRoundBracket);
771	    ParserToken s_close(TokenType::ClosingRoundBracket);
772	    ParserExpressionWithOptionalAlias p_expression(false);
773	    ParserList p_command(std::make_unique<ParserExpressionWithOptionalAlias>(false),
774	                          std::make_unique<ParserToken>(TokenType::Comma), true);
775	
776	    do
777	    {
778	        Pos begin = pos;
779	        ASTPtr command;
780	        if (!s_open.ignore(pos, expected))
781	        {
782	            pos = begin;
783	            if (!p_expression.parse(pos, command, expected))
784	            {
785	                return false;
786	            }
787	            auto list = std::make_shared<ASTExpressionList>(',');
788	            list->children.push_back(command);
789	            command = std::move(list);
790	        }
791	        else
792	        {
793	            if (!p_command.parse(pos, command, expected))
794	                return false;
795	
796	            if (!s_close.ignore(pos, expected))
797	                break;
798	        }
799	
800	        command_list->children.push_back(command);
801	    }
802	    while (s_comma.ignore(pos, expected));
803	
804	    return true;
805	}
