python3 - <<"EOF"
p = "src/Common/ThreadPool.h"
s = open(p).read()

old1 = "            SCOPE_EXIT(state->event.set());\n"
new1 = """            SCOPE_EXIT(
            {
                state->finished = true;
                state->event.set();
            });
"""
assert s.count(old1) == 1, "old1"
s = s.replace(old1, new1)

old2 = """    ~ThreadFromGlobalPool()
    {
        if (initialized())
            abort();
    }
"""
new2 = """    ~ThreadFromGlobalPool()
    {
        /// The problem is that the our ThreadFromGlobalPool can be actually finished
        /// before we try to join the thread or check whether it is joinable or not.
        /// In some places we have code like:
        ///     if (thread->joinable())
        ///         thread->join();
        /// Where join() won'"'"'t be executed in case when we call it
        /// from the same std::thread and it will end to std::abort().
        /// So we just do nothing in this case
        if (state->finished)
            return;

        if (initialized())
            abort();
    }
"""
assert s.count(old2) == 1, "old2"
s = s.replace(old2, new2)

old3 = """        /// The state used in this object and inside the thread job.
        Poco::Event event;
    };
"""
new3 = """        /// The state used in this object and inside the thread job.
        Poco::Event event;

        /// To allow joining to the same std::thread after finishing
        std::atomic<bool> finished{false};
    };
"""
assert s.count(old3) == 1, "old3"
s = s.replace(old3, new3)

open(p, "w").write(s)
