25	class ParallelReplicasReadingCoordinator::Impl
26	{
27	public:
28	    using PartitionReadRequestPtr = std::unique_ptr<PartitionReadRequest>;
29	    using PartToMarkRanges = std::map<PartToRead::PartAndProjectionNames, HalfIntervals>;
30	
31	    struct PartitionReading
32	    {
33	        PartSegments part_ranges;
34	        PartToMarkRanges mark_ranges_in_part;
35	    };
36	
37	    using PartitionToBlockRanges = std::map<String, PartitionReading>;
38	    PartitionToBlockRanges partitions;
39	
40	    std::mutex mutex;
41	
42	    PartitionReadResponse handleRequest(PartitionReadRequest request);
43	};
44	
45	
46	PartitionReadResponse ParallelReplicasReadingCoordinator::Impl::handleRequest(PartitionReadRequest request)
47	{
48	    AtomicStopwatch watch;
49	    std::lock_guard lock(mutex);
50	
51	    auto partition_it = partitions.find(request.partition_id);
52	
53	    SCOPE_EXIT({
54	        LOG_TRACE(&Poco::Logger::get("ParallelReplicasReadingCoordinator"), "Time for handling request: {}ns", watch.elapsed());
55	    });
56	
57	    PartToRead::PartAndProjectionNames part_and_projection
58	    {
59	        .part = request.part_name,
60	        .projection = request.projection_name
61	    };
62	
63	    /// We are the first who wants to process parts in partition
64	    if (partition_it == partitions.end())
65	    {
66	        PartitionReading partition_reading;
67	
68	        PartToRead part_to_read;
69	        part_to_read.range = request.block_range;
70	        part_to_read.name = part_and_projection;
71	
72	        partition_reading.part_ranges.addPart(std::move(part_to_read));
73	
74	        /// As this query is first in partition, we will accept all ranges from it.
75	        /// We need just to update our state.
76	        auto request_ranges = HalfIntervals::initializeFromMarkRanges(request.mark_ranges);
77	        auto mark_ranges_index = HalfIntervals::initializeWithEntireSpace();
78	        mark_ranges_index.intersect(request_ranges.negate());
79	
80	        partition_reading.mark_ranges_in_part.insert({part_and_projection, std::move(mark_ranges_index)});
81	        partitions.insert({request.partition_id, std::move(partition_reading)});
82	
83	        return {.denied = false, .mark_ranges = std::move(request.mark_ranges)};
84	    }
85	
86	    auto & partition_reading = partition_it->second;
87	
88	    PartToRead part_to_read;
89	    part_to_read.range = request.block_range;
90	    part_to_read.name = part_and_projection;
91	
92	    auto part_intersection_res = partition_reading.part_ranges.getIntersectionResult(part_to_read);
93	
94	    switch (part_intersection_res)
95	    {
96	        case PartSegments::IntersectionResult::REJECT:
97	        {
98	            return {.denied = true, .mark_ranges = {}};
99	        }
100	        case PartSegments::IntersectionResult::EXACTLY_ONE_INTERSECTION:
101	        {
102	            auto marks_it = partition_reading.mark_ranges_in_part.find(part_and_projection);
103	
104	            auto & intervals_to_do = marks_it->second;
105	            auto result = HalfIntervals::initializeFromMarkRanges(request.mark_ranges);
106	            result.intersect(intervals_to_do);
107	
108	            /// Update intervals_to_do
109	            intervals_to_do.intersect(HalfIntervals::initializeFromMarkRanges(std::move(request.mark_ranges)).negate());
110	
111	            auto result_ranges = result.convertToMarkRangesFinal();
112	            const bool denied = result_ranges.empty();
113	            return {.denied = denied, .mark_ranges = std::move(result_ranges)};
114	        }
115	        case PartSegments::IntersectionResult::NO_INTERSECTION:
116	        {
117	            partition_reading.part_ranges.addPart(std::move(part_to_read));
118	
119	            auto mark_ranges_index = HalfIntervals::initializeWithEntireSpace().intersect(
120	            HalfIntervals::initializeFromMarkRanges(request.mark_ranges).negate()
121	            );
122	            partition_reading.mark_ranges_in_part.insert({part_and_projection, std::move(mark_ranges_index)});
123	
124	            return {.denied = false, .mark_ranges = std::move(request.mark_ranges)};
125	        }
126	    }
127	
128	    __builtin_unreachable();
129	}
130	
131	PartitionReadResponse ParallelReplicasReadingCoordinator::handleRequest(PartitionReadRequest request)
132	{
133	    return pimpl->handleRequest(std::move(request));
134	}
