100	std::future<IAsynchronousReader::Result> AsynchronousReadIndirectBufferFromRemoteFS::asyncReadInto(char * data, size_t size)
101	{
102	    IAsynchronousReader::Request request;
103	    request.descriptor = std::make_shared<RemoteFSFileDescriptor>(impl);
104	    request.buf = data;
105	    request.size = size;
106	    request.offset = file_offset_of_buffer_end;
107	    request.priority = priority;
108	
109	    if (bytes_to_ignore)
110	    {
111	        request.ignore = bytes_to_ignore;
112	        bytes_to_ignore = 0;
113	    }
114	    return reader->submit(request);
115	}
