896	{
897	    auto begin = pos;
898	
899	    /// If no TIMESTAMP keyword, go to the nested parser.
900	    if (!ParserKeyword("TIMESTAMP").ignore(pos, expected))
901	        return next_parser.parse(pos, node, expected);
902	
903	    ASTPtr expr;
904	    if (!ParserStringLiteral().parse(pos, expr, expected))
905	    {
906	        pos = begin;
