912	
913	    /// function arguments
914	    auto exp_list = std::make_shared<ASTExpressionList>();
915	
916	    /// the first argument of the function is the previous element, the second is the next one
917	    function->name = "toDateTime";
918	    function->arguments = exp_list;
919	    function->children.push_back(exp_list);
920	
921	    exp_list->children.push_back(expr);
922	
923	    node = function;
