315	void ExpressionAnalyzer::analyzeAggregation(ActionsDAGPtr & temp_actions)
316	{
317	    /** Find aggregation keys (aggregation_keys), information about aggregate functions (aggregate_descriptions),
318	     *  as well as a set of columns obtained after the aggregation, if any,
319	     *  or after all the actions that are usually performed before aggregation (aggregated_columns).
320	     *
321	     * Everything below (compiling temporary ExpressionActions) - only for the purpose of query analysis (type output).
322	     */
323	
324	    auto * select_query = query->as<ASTSelectQuery>();
325	
326	    makeAggregateDescriptions(temp_actions, aggregate_descriptions);
327	    has_aggregation = !aggregate_descriptions.empty() || (select_query && (select_query->groupBy() || select_query->having()));
328	
329	    if (!has_aggregation)
330	    {
331	        aggregated_columns = temp_actions->getNamesAndTypesList();
332	        return;
333	    }
334	
335	    /// Find out aggregation keys.
336	    if (select_query)
337	    {
338	        if (ASTPtr group_by_ast = select_query->groupBy())
339	        {
340	            NameToIndexMap unique_keys;
341	            ASTs & group_asts = group_by_ast->children;
342	
343	            if (select_query->group_by_with_rollup)
344	                group_by_kind = GroupByKind::ROLLUP;
345	            else if (select_query->group_by_with_cube)
346	                group_by_kind = GroupByKind::CUBE;
347	            else if (select_query->group_by_with_grouping_sets && group_asts.size() > 1)
348	                group_by_kind = GroupByKind::GROUPING_SETS;
349	            else
350	                group_by_kind = GroupByKind::ORDINARY;
351	            bool use_nulls = group_by_kind != GroupByKind::ORDINARY && getContext()->getSettingsRef().group_by_use_nulls;
352	
353	            /// For GROUPING SETS with multiple groups we always add virtual __grouping_set column
354	            /// With set number, which is used as an additional key at the stage of merging aggregating data.
355	            if (group_by_kind != GroupByKind::ORDINARY)
356	                aggregated_columns.emplace_back("__grouping_set", std::make_shared<DataTypeUInt64>());
357	
358	            for (ssize_t i = 0; i < static_cast<ssize_t>(group_asts.size()); ++i)
359	            {
360	                ssize_t size = group_asts.size();
361	
362	                if (getContext()->getSettingsRef().enable_positional_arguments)
363	                    replaceForPositionalArguments(group_asts[i], select_query, ASTSelectQuery::Expression::GROUP_BY);
364	
365	                if (select_query->group_by_with_grouping_sets)
366	                {
367	                    ASTs group_elements_ast;
368	                    const ASTExpressionList * group_ast_element = group_asts[i]->as<const ASTExpressionList>();
369	                    group_elements_ast = group_ast_element->children;
370	
371	                    NamesAndTypesList grouping_set_list;
372	                    ColumnNumbers grouping_set_indexes_list;
373	
374	                    for (ssize_t j = 0; j < ssize_t(group_elements_ast.size()); ++j)
375	                    {
376	                        getRootActionsNoMakeSet(group_elements_ast[j], temp_actions, false);
377	
378	                        ssize_t group_size = group_elements_ast.size();
379	                        const auto & column_name = group_elements_ast[j]->getColumnName();
380	                        const auto * node = temp_actions->tryFindInIndex(column_name);
381	                        if (!node)
382	                            throw Exception("Unknown identifier (in GROUP BY): " + column_name, ErrorCodes::UNKNOWN_IDENTIFIER);
383	
384	                        /// Only removes constant keys if it's an initiator or distributed_group_by_no_merge is enabled.
385	                        if (getContext()->getClientInfo().distributed_depth == 0 || settings.distributed_group_by_no_merge > 0)
386	                        {
387	                            /// Constant expressions have non-null column pointer at this stage.
388	                            if (node->column && isColumnConst(*node->column))
389	                            {
390	                                select_query->group_by_with_constant_keys = true;
391	
392	                                /// But don't remove last key column if no aggregate functions, otherwise aggregation will not work.
393	                                if (!aggregate_descriptions.empty() || group_size > 1)
394	                                {
395	                                    if (j + 1 < static_cast<ssize_t>(group_size))
396	                                        group_elements_ast[j] = std::move(group_elements_ast.back());
397	
398	                                    group_elements_ast.pop_back();
399	
400	                                    --j;
401	                                    continue;
402	                                }
403	                            }
404	                        }
405	
406	                        NameAndTypePair key{column_name, use_nulls ? makeNullableSafe(node->result_type) : node->result_type };
407	
408	                        grouping_set_list.push_back(key);
409	
410	                        /// Aggregation keys are unique.
411	                        if (!unique_keys.contains(key.name))
412	                        {
413	                            unique_keys[key.name] = aggregation_keys.size();
414	                            grouping_set_indexes_list.push_back(aggregation_keys.size());
415	                            aggregation_keys.push_back(key);
416	
417	                            /// Key is no longer needed, therefore we can save a little by moving it.
418	                            aggregated_columns.push_back(std::move(key));
419	                        }
420	                        else
421	                        {
422	                            grouping_set_indexes_list.push_back(unique_keys[key.name]);
423	                        }
424	                    }
425	
426	                    aggregation_keys_list.push_back(std::move(grouping_set_list));
427	                    aggregation_keys_indexes_list.push_back(std::move(grouping_set_indexes_list));
428	                }
429	                else
430	                {
431	                    getRootActionsNoMakeSet(group_asts[i], temp_actions, false);
432	
433	                    const auto & column_name = group_asts[i]->getColumnName();
434	                    const auto * node = temp_actions->tryFindInIndex(column_name);
435	                    if (!node)
436	                        throw Exception("Unknown identifier (in GROUP BY): " + column_name, ErrorCodes::UNKNOWN_IDENTIFIER);
437	
438	                    /// Only removes constant keys if it's an initiator or distributed_group_by_no_merge is enabled.
439	                    if (getContext()->getClientInfo().distributed_depth == 0 || settings.distributed_group_by_no_merge > 0)
440	                    {
441	                        /// Constant expressions have non-null column pointer at this stage.
442	                        if (node->column && isColumnConst(*node->column))
443	                        {
444	                            select_query->group_by_with_constant_keys = true;
445	
446	                            /// But don't remove last key column if no aggregate functions, otherwise aggregation will not work.
447	                            if (!aggregate_descriptions.empty() || size > 1)
448	                            {
449	                                if (i + 1 < static_cast<ssize_t>(size))
450	                                    group_asts[i] = std::move(group_asts.back());
451	
452	                                group_asts.pop_back();
453	
454	                                --i;
455	                                continue;
456	                            }
457	                        }
458	                    }
459	
460	                    NameAndTypePair key = NameAndTypePair{ column_name, use_nulls ? makeNullableSafe(node->result_type) : node->result_type };
461	
462	                    /// Aggregation keys are uniqued.
463	                    if (!unique_keys.contains(key.name))
464	                    {
465	                        unique_keys[key.name] = aggregation_keys.size();
466	                        aggregation_keys.push_back(key);
467	
468	                        /// Key is no longer needed, therefore we can save a little by moving it.
469	                        aggregated_columns.push_back(std::move(key));
470	                    }
471	                }
472	            }
473	
474	            if (!select_query->group_by_with_grouping_sets)
475	            {
476	                auto & list = aggregation_keys_indexes_list.emplace_back();
477	                for (size_t i = 0; i < aggregation_keys.size(); ++i)
478	                    list.push_back(i);
479	            }
480	
481	            if (group_asts.empty())
482	            {
483	                select_query->setExpression(ASTSelectQuery::Expression::GROUP_BY, {});
484	                has_aggregation = select_query->having() || !aggregate_descriptions.empty();
485	            }
486	        }
487	
488	        /// Constant expressions are already removed during first 'analyze' run.
489	        /// So for second `analyze` information is taken from select_query.
490	        has_const_aggregation_keys = select_query->group_by_with_constant_keys;
491	    }
492	    else
493	        aggregated_columns = temp_actions->getNamesAndTypesList();
494	
495	    for (const auto & desc : aggregate_descriptions)
496	        aggregated_columns.emplace_back(desc.column_name, desc.function->getReturnType());
497	}
