    Aws::S3::Model::GetObjectOutcome outcome = client_ptr->GetObject(req);"""),
    ]),
    # 4. WriteBufferFromS3.h: for_disk_s3 flag.
    ("src/IO/WriteBufferFromS3.h", [
        ("        FileCachePtr cache_ = nullptr);",
