        ("    FileCachePtr cache;\n    size_t current_download_offset = 0;",
         """    FileCachePtr cache;

    /// Whether the buffer writes to a disk over S3 object storage (used for profile events).
    bool for_disk_s3 = false;

    size_t current_download_offset = 0;"""),
    ]),
    # 5. WriteBufferFromS3.cpp: count upload-related calls.
    ("src/IO/WriteBufferFromS3.cpp", [
        ("    extern const Event CachedReadBufferCacheWriteBytes;\n",
