        ("    auto outcome = client_ptr->UploadPart(task.req);",
         """    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3UploadPart : ProfileEvents::S3UploadPart);

    auto outcome = client_ptr->UploadPart(task.req);"""),
        ("    auto outcome = client_ptr->CompleteMultipartUpload(req);",
         """    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3CompleteMultipartUpload : ProfileEvents::S3CompleteMultipartUpload);

    auto outcome = client_ptr->CompleteMultipartUpload(req);"""),
        ("    auto outcome = client_ptr->PutObject(task.req);",
         """    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3PutObject : ProfileEvents::S3PutObject);

    auto outcome = client_ptr->PutObject(task.req);"""),
    ]),
    # 6. ReadBufferFromRemoteFSGather.cpp: gather reader is only used by S3 disk.
    ("src/Disks/IO/ReadBufferFromRemoteFSGather.cpp", [
