374	void StorageEmbeddedRocksDB::initDB()
375	{
376	    rocksdb::Status status;
377	    rocksdb::Options base;
378	    rocksdb::DB * db;
379	
380	    base.create_if_missing = true;
381	    base.compression = rocksdb::CompressionType::kZSTD;
382	    base.statistics = rocksdb::CreateDBStatistics();
383	    /// It is too verbose by default, and in fact we don't care about rocksdb logs at all.
384	    base.info_log_level = rocksdb::ERROR_LEVEL;
385	
386	    rocksdb::Options merged = base;
387	
388	    const auto & config = getContext()->getConfigRef();
389	    if (config.has("rocksdb.options"))
390	    {
391	        auto config_options = getOptionsFromConfig(config, "rocksdb.options");
392	        status = rocksdb::GetDBOptionsFromMap(merged, config_options, &merged);
393	        if (!status.ok())
394	        {
395	            throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from 'rocksdb.options' at: {}: {}",
396	                rocksdb_dir, status.ToString());
397	        }
398	    }
399	    if (config.has("rocksdb.column_family_options"))
400	    {
401	        auto column_family_options = getOptionsFromConfig(config, "rocksdb.column_family_options");
402	        status = rocksdb::GetColumnFamilyOptionsFromMap(merged, column_family_options, &merged);
403	        if (!status.ok())
404	        {
405	            throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from 'rocksdb.options' at: {}: {}",
406	                rocksdb_dir, status.ToString());
407	        }
408	    }
409	
410	    if (config.has("rocksdb.tables"))
411	    {
412	        auto table_name = getStorageID().getTableName();
413	
414	        Poco::Util::AbstractConfiguration::Keys keys;
415	        config.keys("rocksdb.tables", keys);
416	
417	        for (const auto & key : keys)
418	        {
419	            const String key_prefix = "rocksdb.tables." + key;
420	            if (config.getString(key_prefix + ".name") != table_name)
421	                continue;
422	
423	            String config_key = key_prefix + ".options";
424	            if (config.has(config_key))
425	            {
426	                auto table_config_options = getOptionsFromConfig(config, config_key);
427	                status = rocksdb::GetDBOptionsFromMap(merged, table_config_options, &merged);
428	                if (!status.ok())
429	                {
430	                    throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from '{}' at: {}: {}",
431	                        config_key, rocksdb_dir, status.ToString());
432	                }
433	            }
434	
435	            config_key = key_prefix + ".column_family_options";
436	            if (config.has(config_key))
437	            {
438	                auto table_column_family_options = getOptionsFromConfig(config, config_key);
439	                status = rocksdb::GetColumnFamilyOptionsFromMap(merged, table_column_family_options, &merged);
440	                if (!status.ok())
441	                {
442	                    throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to merge rocksdb options from '{}' at: {}: {}",
443	                        config_key, rocksdb_dir, status.ToString());
444	                }
445	            }
446	        }
447	    }
448	
449	    status = rocksdb::DB::Open(merged, rocksdb_dir, &db);
450	
451	    if (!status.ok())
452	    {
453	        throw Exception(ErrorCodes::ROCKSDB_ERROR, "Fail to open rocksdb path at: {}: {}",
454	            rocksdb_dir, status.ToString());
455	    }
456	    /// It's ok just to wrap db with unique_ptr, from rdb documentation: "when you are done with a database, just delete the database object"
457	    rocksdb_ptr = std::unique_ptr<rocksdb::DB>(db);
458	}
