16	/// Information about partition and the range of blocks contained in the part.
17	/// Allows determining if parts are disjoint or one part fully contains the other.
18	struct MergeTreePartInfo
19	{
20	    String partition_id;
21	    Int64 min_block = 0;
22	    Int64 max_block = 0;
23	    UInt32 level = 0;
24	    Int64 mutation = 0;   /// If the part has been mutated or contains mutated parts, is equal to mutation version number.
25	
26	    bool use_leagcy_max_level = false;  /// For compatibility. TODO remove it
27	
28	    MergeTreePartInfo() = default;
29	
30	    MergeTreePartInfo(String partition_id_, Int64 min_block_, Int64 max_block_, UInt32 level_)
31	        : partition_id(std::move(partition_id_)), min_block(min_block_), max_block(max_block_), level(level_)
32	    {
33	    }
34	
35	    MergeTreePartInfo(String partition_id_, Int64 min_block_, Int64 max_block_, UInt32 level_, Int64 mutation_)
36	        : partition_id(std::move(partition_id_)), min_block(min_block_), max_block(max_block_), level(level_), mutation(mutation_)
37	    {
38	    }
39	
40	    bool operator<(const MergeTreePartInfo & rhs) const
41	    {
42	        return std::forward_as_tuple(partition_id, min_block, max_block, level, mutation)
43	            < std::forward_as_tuple(rhs.partition_id, rhs.min_block, rhs.max_block, rhs.level, rhs.mutation);
44	    }
45	
46	    bool operator==(const MergeTreePartInfo & rhs) const
47	    {
48	        return !(*this != rhs);
49	    }
50	
51	    bool operator!=(const MergeTreePartInfo & rhs) const
52	    {
53	        return *this < rhs || rhs < *this;
54	    }
55	
56	    /// Get block number that can be used to determine which mutations we still need to apply to this part
57	    /// (all mutations with version greater than this block number).
58	    Int64 getDataVersion() const { return mutation ? mutation : min_block; }
59	
60	    /// True if contains rhs (this part is obtained by merging rhs with some other parts or mutating rhs)
61	    bool contains(const MergeTreePartInfo & rhs) const
62	    {
63	        /// Containing part may have equal level iff block numbers are equal (unless level is MAX_LEVEL)
64	        /// (e.g. all_0_5_2 does not contain all_0_4_2, but all_0_5_3 or all_0_4_2_9 do)
65	        bool strictly_contains_block_range = (min_block == rhs.min_block && max_block == rhs.max_block) || level > rhs.level
66	            || level == MAX_LEVEL || level == LEGACY_MAX_LEVEL;
67	        return partition_id == rhs.partition_id        /// Parts for different partitions are not merged
68	            && min_block <= rhs.min_block
69	            && max_block >= rhs.max_block
70	            && level >= rhs.level
71	            && mutation >= rhs.mutation
72	            && strictly_contains_block_range;
73	    }
74	
75	    /// Part was created with mutation of parent_candidate part
76	    bool isMutationChildOf(const MergeTreePartInfo & parent_candidate) const
77	    {
78	        return partition_id == parent_candidate.partition_id
79	            && min_block == parent_candidate.min_block
80	            && max_block == parent_candidate.max_block
81	            && level == parent_candidate.level
82	            && mutation >= parent_candidate.mutation;
83	    }
84	
85	    /// Return part mutation version, if part wasn't mutated return zero
86	    Int64 getMutationVersion() const
87	    {
88	        return mutation;
89	    }
90	
91	    /// True if parts do not intersect in any way.
92	    bool isDisjoint(const MergeTreePartInfo & rhs) const
93	    {
94	        return partition_id != rhs.partition_id
95	            || min_block > rhs.max_block
96	            || max_block < rhs.min_block;
97	    }
98	
99	    bool isFakeDropRangePart() const
100	    {
101	        /// Another max level was previously used for REPLACE/MOVE PARTITION
102	        auto another_max_level = std::numeric_limits<decltype(level)>::max();
103	        return level == MergeTreePartInfo::MAX_LEVEL || level == another_max_level;
104	    }
105	
106	    String getPartName() const;
107	    String getPartNameV0(DayNum left_date, DayNum right_date) const;
108	    UInt64 getBlocksCount() const
109	    {
110	        return static_cast<UInt64>(max_block - min_block + 1);
111	    }
112	
113	    /// Simple sanity check for partition ID. Checking that it's not too long or too short, doesn't contain a lot of '_'.
114	    static void validatePartitionID(const String & partition_id, MergeTreeDataFormatVersion format_version);
115	
116	    static MergeTreePartInfo fromPartName(const String & part_name, MergeTreeDataFormatVersion format_version);  // -V1071
117	
118	    static std::optional<MergeTreePartInfo> tryParsePartName(
119	        std::string_view part_name, MergeTreeDataFormatVersion format_version);
120	
121	    static void parseMinMaxDatesFromPartName(const String & part_name, DayNum & min_date, DayNum & max_date);
122	
123	    static bool contains(const String & outer_part_name, const String & inner_part_name, MergeTreeDataFormatVersion format_version);
124	
125	    static constexpr UInt32 MAX_LEVEL = 999999999;
126	    static constexpr UInt32 MAX_BLOCK_NUMBER = 999999999;
127	
128	    static constexpr UInt32 LEGACY_MAX_LEVEL = std::numeric_limits<decltype(level)>::max();
129	};
